// ================= VERİ: el-Arabiyyetü beyne yedeyk 3, 9. ünite — المُساواةُ الحَقَّةُ =================
// Bloklar k2ortak/uygulama.js içinde çizilir. Asıl kayıt parçaları: zaman.js (ZAMAN); kaydı olmayan metinler gömülü okunuşla çalar.
var UNITE = { no: 9, ar: "المُساواةُ الحَقَّةُ", tr: "True Equality", pfx: "k3u9:",
  giris: "Unit 9: practical examples of equality in Islam (acts of worship, prescribed punishments, retribution, judgment). Grammar: the absolute object (mafʿūl muṭlaq); the object of purpose (mafʿūl lahu). Spelling: the hamza in the middle of a word." };
var DERSLER = [
// ---------------- DERS 57 ----------------
{ no: 57, kisa: "المُساواةُ الحَقَّةُ", ar: "المُساواةُ الحَقَّةُ", tr: "True Equality", ozet: "Reading text: practical examples of equality in Islam; comprehension exercises.", bloklar: [
 { t: "hazirlik", ar: "ما قَبْلَ القِراءَةِ", ogeler: [
  ["اذْكُرْ بَعْضَ مَظاهِرِ (صُوَرِ) المُساواةِ في الإِسْلامِ.", "Name some aspects of equality in Islam."], ["الحَجُّ صورَةٌ صادِقَةٌ لِلْمُساواةِ، وَضِّحْ ذلِكَ.", "Hajj is a true picture of equality; explain."],
  ["بِإِلْقاءِ نَظْرَةٍ عَلى العُنْوانِ؛ هَلْ تَفْهَمُ أَنَّ هُناكَ مُساواةً حَقَّةً وَأُخْرى غَيْرَ حَقَّةٍ؟ وَضِّحْ ذلِكَ.", "Looking at the title, do you understand that there is a true equality and a non-true equality? Explain."]] },
 { t: "metin", resim: ["saf"], paragraf: [
  [["قَرَّرَ الإِسْلامُ مَبْدَأَ المُساواةِ، كَما قَرَّرَ مَبْدَأَ الحُرِّيَّةِ وَالإِخاءِ في العالَمِ، وَقَدْ سَبَقَ في ذلِكَ دُعاةَ المَبادِئِ في العَصْرِ الحَديثِ.", "Islam laid down the principle of equality just as it laid down the principle of freedom and brotherhood in the world; in this it preceded the advocates of principles of the modern age.", "m57-0"]],
  [["وَلَمْ يَكُنْ تَقْريرُ هذِهِ المَبادِئِ تَقْريرًا نَظَرِيًّا، كَما حَدَثَ في بَعْضِ الدُّوَلِ، وَفي هَيْئَةِ الأُمَمِ المُتَّحِدَةِ؛ حَيْثُ وُضِعَتِ المَبادِئُ وَلَمْ يُنَفَّذْ مِنْها إِلّا القَليلُ بِحَسَبِ ما تُريدُ الأُمَمُ القَوِيَّةُ. وَإِنَّما دَعا الإِسْلامُ إِلى هذِهِ المَبادِئِ، وَطَبَّقَها النَّبِيُّ ﷺ وَتَبِعَهُ الصَّحابَةُ، وَعَمَّتِ المُجْتَمَعَ الإِسْلامِيَّ في أَقْطارِ الأَرْضِ. وَنَذْكُرُ فيما يَلي صُوَرًا عَمَلِيَّةً لِلْمُساواةِ طُبِّقَتْ وَتُطَبَّقُ في الدَّوْلَةِ الإِسْلامِيَّةِ:", "The laying down of these principles was not theoretical, as it was in some states and in the United Nations, where principles were laid down but only a little of them was applied, to the extent that the strong nations wished. Islam called to these principles; the Prophet ﷺ applied them, the Companions followed him, and the principles embraced Islamic society in every corner of the earth. Below we mention practical examples of equality applied in the Islamic state:", "m57-1"]],
  [["التَّكاليفُ الشَّرْعِيَّةُ - مِنْ صَلاةٍ، وَصَوْمٍ، وَزَكاةٍ، وَحَجٍّ وَغَيْرِها - عامَّةٌ يُطالَبُ كُلُّ مُسْلِمٍ بِأَنْ يُؤَدِّيَها دونَ اسْتِثْناءِ أَحَدٍ مِنْها.", "Prayer, fasting, zakat, Hajj and similar Sharia obligations are general; every Muslim is asked to perform them, no one excepted.", "m57-2"]],
  [["الصَّلاةُ - وَهِيَ الرُّكْنُ الثّاني مِنْ أَرْكانِ الإِسْلامِ - تَظْهَرُ فيها المُساواةُ؛ إِذْ يَقِفُ المُسْلِمونَ صُفوفًا، يَتَجاوَرُ فيها الصَّغيرُ وَالكَبيرُ، وَالغَنِيُّ وَالفَقيرُ، وَالأَبْيَضُ وَالأَسْوَدُ، وَكُلُّهُمْ يُصَلّونَ لِإِلهٍ واحِدٍ. وَكَذلِكَ تَظْهَرُ المُساواةُ في مَلابِسِ الحَجِّ المُوَحَّدَةِ وَفي أَداءِ مَناسِكِهِ.", "Equality is visible in prayer, the second pillar of Islam: Muslims stand in rows; small and big, rich and poor, white and black come side by side and all pray to one God. Equality is also visible in the uniform clothes of Hajj and in the performance of the rites.", "m57-3"]],
  [["تُنَفَّذُ الحُدودُ عَلى مَنْ فَعَلَ ما يوجِبُ حَدًّا مِنَ المُسْلِمينَ بِلا اسْتِثْناءٍ، بِخِلافِ ما كانَتْ عَلَيْهِ كَثيرٌ مِنَ الأُمَمِ الَّتي كانَتْ قَوانينُها تُنَفَّذُ عَلى العامَّةِ فَحَسْبُ. وَقَدْ حَدَثَ أَنْ سَرَقَتِ امْرَأَةٌ مِنْ بَني مَخْزومٍ، وَاسْتَشْفَعَ أَهْلُها بِأُسامَةَ بْنِ زَيْدٍ لِحُبِّ الرَّسولِ ﷺ إِيّاهُ، فَلَمّا كَلَّمَ النَّبِيَّ ﷺ فيها غَضِبَ، وَقالَ لَهُ: «أَتَشْفَعُ في حَدٍّ مِنْ حُدودِ اللهِ؟» ثُمَّ قامَ فَخَطَبَ، فَقالَ: «يا أَيُّها النّاسُ، إِنَّما ضَلَّ مَنْ قَبْلَكُمْ أَنَّهُمْ كانوا إِذا سَرَقَ الشَّريفُ تَرَكوهُ، وَإِذا سَرَقَ الضَّعيفُ فيهِمْ أَقاموا عَلَيْهِ الحَدَّ، وَايْمُ اللهِ لَوْ أَنَّ فاطِمَةَ بِنْتَ مُحَمَّدٍ ﷺ سَرَقَتْ لَقَطَعَ مُحَمَّدٌ ﷺ يَدَها».", "The prescribed punishments are applied to every Muslim who commits a crime requiring a ḥadd, without exception; unlike the situation of many nations whose laws are applied only to the common people. A woman of the Banū Makhzūm had stolen; her family, because the Messenger ﷺ loved him, made Usāma ibn Zayd the intermediary. When Usāma spoke to the Prophet ﷺ about her, the Prophet became angry and said, “Are you interceding concerning one of God's prescribed punishments?” Then he stood and gave a sermon: “O people! Those before you went astray because of this: when a noble among them stole they would let him go, and when a weak one stole they would apply the punishment to him. By God, if Fāṭima, the daughter of Muhammad, stole, Muhammad would cut off her hand.”", "m57-4"]],
  [["يُراعى تَنْفيذُ القِصاصِ بَيْنَ النّاسِ جَميعًا، وَإِنِ اخْتَلَفَتْ دَرَجاتُ المُعْتَدي وَالمُعْتَدى عَلَيْهِ. مِنْ ذلِكَ أَنَّ رَجُلًا جاءَ يَشْكو إِلى عُمَرَ بْنِ الخَطّابِ، وَهُوَ مَشْغولٌ، فَقالَ لَهُ: «أَتَتْرُكونَ الخَليفَةَ حينَ يَكونُ فارِغًا، حَتّى إِذا شُغِلَ بِأَمْرِ المُسْلِمينَ أَتَيْتُموهُ؟» وَضَرَبَهُ بِالدِّرَّةِ (العَصا)، فَرَجَعَ الرَّجُلُ حَزينًا. فَتَذَكَّرَ عُمَرُ أَنَّهُ ظَلَمَهُ، فَدَعا بِهِ، وَأَعْطاهُ الدِّرَّةَ، وَقالَ لَهُ: اضْرِبْني كَما ضَرَبْتُكَ. فَأَبى الرَّجُلُ وَقالَ: تَرَكْتُ حَقّي لِلّهِ وَلَكَ، فَقالَ عُمَرُ: إِمّا أَنْ تَتْرُكَهُ لِلّهِ وَحْدَهُ، وَإِمّا أَنْ تَأْخُذَ حَقَّكَ. فَقالَ لَهُ الرَّجُلُ: تَرَكْتُهُ لِلّهِ.", "Retribution is observed among all people, even if the assailant and the one assaulted differ in rank. An example: a man came to ʿUmar ibn al-Khaṭṭāb to complain while he was busy. ʿUmar said, “You leave the caliph when he is free and come when he is busy with the Muslims' affairs?” and struck him with a whip (dirra). The man returned sad. ʿUmar remembered that he had wronged him, had him called, gave him the whip and said, “Strike me as I struck you.” The man refused: “I have given up my right for God's sake and for yours.” ʿUmar said, “Either you give it up for God alone or you take your right.” The man said, “I gave it up for God.”", "m57-5"],
   ["وَرَجَعَ عُمَرُ إِلى مَنْزِلِهِ، وَصَلّى رَكْعَتَيْنِ، ثُمَّ جَلَسَ يَقولُ لِنَفْسِهِ: يا ابْنَ الخَطّابِ كُنْتَ وَضيعًا فَرَفَعَكَ اللهُ، وَضالًّا فَهَداكَ اللهُ، وَضَعيفًا فَأَعَزَّكَ اللهُ وَجَعَلَكَ خَليفَةً، فَأَتى رَجُلٌ يَسْتَعينُ بِكَ عَلى دَفْعِ الظُّلْمِ فَظَلَمْتَهُ، ما تَقولُ لِرَبِّكَ غَدًا إِذا أَتَيْتَهُ؟ وَظَلَّ يُحاسِبُ نَفْسَهُ حَتّى أَشْفَقَ النّاسُ عَلَيْهِ.", "ʿUmar returned to his house, prayed two rakʿas, then sat and said to himself: “O son of al-Khaṭṭāb! You were lowly, and God raised you; you were astray, and God guided you; you were weak, and God made you mighty and made you caliph. A man came asking your help to ward off injustice, and you wronged him. Tomorrow when you come to your Lord, what will you say to Him?” And he continued calling himself to account until people felt pity for him.", "m57-6"]],
  [["وَمِنْ هذا المِثالِ، تَرى كَيْفَ أَنَّ المُسْلِمينَ، كانوا يُطَبِّقونَ المُساواةَ: وَهَلْ هُناكَ أَرْوَعُ مِنْ أَنْ يَتَأَلَّمَ عُمَرُ لِشَيْءٍ يَسيرٍ فَعَلَهُ، فَيَسْتَرْضِيَ الرَّجُلَ، وَيَدْعُوَهُ إِلى القِصاصِ مِنْهُ، ثُمَّ يُؤَنِّبَ نَفْسَهُ هذا التَّأْنيبَ خَشْيَةً مِنَ اللهِ تَعالى!", "From this example you see how the Muslims applied equality: what could be more beautiful than ʿUmar's grieving over a small thing he had done, his trying to satisfy the man, his calling him to take retribution from him, and then his rebuking himself thus out of fear of God!", "m57-7"]],
  [["وَهذا أَبو بَكْرٍ في خُطْبَتِهِ عِنْدَما وَلِيَ الخِلافَةَ يَقولُ: «أَيُّها النّاسُ، إِنّي وُلّيتُ عَلَيْكُمْ وَلَسْتُ بِخَيْرِكُمْ».", "Here is Abū Bakr, who, when he took on the caliphate, said in his sermon: “O people! I have been made ruler over you, but I am not the best of you.”", "m57-8"]],
  [["تَحْقيقُ المُساواةِ بَيْنَ النّاسِ عِنْدَ التَّقاضي، عَلى دَرَجَةٍ واحِدَةٍ، لا فَرْقَ بَيْنَ كَبيرِهِمْ وَصَغيرِهِمْ، وَلا بَيْنَ المُسْلِمِ وَغَيْرِهِ، وَنَذْكُرُ لِذلِكَ مِثالَيْنِ:", "Ensuring equality among people to the same degree when being judged; there is no difference between their elders and their young, between a Muslim and another. We give two examples of this:", "m57-9"]],
  [["أَوَّلُهُما: جاءَ رَجُلٌ إِلى عُمَرَ يَشْكو عَلِيًّا - رَضِيَ اللهُ عَنْهُما - فَقالَ عُمَرُ: قُمْ يا أَبا الحَسَنِ فَاجْلِسْ مَعَ خَصْمِكَ. فَقامَ مُتَأَلِّمًا، وَجَلَسَ مَعَ خَصْمِهِ، وَتَكَلَّما، ثُمَّ حَكَمَ بَيْنَهُما عُمَرُ، وَخَرَجَ الرَّجُلُ، فَالْتَفَتَ عُمَرُ إِلى عَلِيٍّ، وَقالَ لَهُ: ما لَكَ قَدْ تَغَيَّرَ وَجْهُكَ حينَ أَمَرْتُكَ بِالجُلوسِ مَعَ خَصْمِكَ؟ هَلْ كَرِهْتَ شَيْئًا؟ قالَ: نَعَمْ، فَقَدْ كَنَّيْتَني بِحَضْرَةِ خَصْمي، وَالتَّكْنِيَةُ ضَرْبٌ مِنَ التَّكْريمِ، هَلّا قُلْتَ: قُمْ يا عَلِيُّ فَاجْلِسْ مَعَ خَصْمِكَ؟ فَقَبَّلَهُ عُمَرُ بَيْنَ عَيْنَيْهِ.", "The first: A man came to ʿUmar to complain of ʿAlī (may God be pleased with them both). ʿUmar said, “Get up, O Abū al-Ḥasan, and sit with your opponent.” ʿAlī got up hurt and sat with his opponent; they spoke, then ʿUmar gave judgment between them. When the man left, ʿUmar turned to ʿAlī and said, “Why did your face change when I ordered you to sit with your opponent? Did you dislike something?” ʿAlī said, “Yes; you called me by my kunya in front of my opponent, and calling by the kunya is a kind of honour. If only you had said, ‘Get up, ʿAlī, and sit with your opponent!’” ʿUmar kissed him between his eyes.", "m57-10"]],
  [["ثانيهِما: ما فَعَلَهُ عُمَرُ مِنَ القِصاصِ مِنْ وَلَدِ عَمْرِو بْنِ العاصِ - وَكانَ أَبوهُ أَميرَ مِصْرَ - لِلْمِصْرِيِّ الَّذي شَكاهُ، ثُمَّ تَأْنيبُهُ لِعَمْرٍو إِذِ اعْتَدى ابْنُهُ، مُعْتَمِدًا عَلى سُلْطانِ أَبيهِ، بِكَلِمَتِهِ المَشْهورَةِ: «يا عَمْرُو، مَتى اسْتَعْبَدْتُمُ النّاسَ وَقَدْ وَلَدَتْهُمْ أُمَّهاتُهُمْ أَحْرارًا؟»", "The second: ʿUmar's taking retribution from the son of ʿAmr ibn al-ʿĀṣ, the emir of Egypt, on behalf of the Egyptian who complained of him; then his rebuking ʿAmr with his famous words because his son had attacked relying on his father's influence: “O ʿAmr! Since when have you enslaved people when their mothers bore them free?”", "m57-11"],
   ["هذا هُوَ الإِسْلامُ يَدْعو إِلى المُساواةِ وَالعَدالَةِ في المُعامَلَةِ. وَهؤُلاءِ هُمُ المُسْلِمونَ يُطَبِّقونَ مَبادِئَهُ، مُخْلِصينَ، فَنَعِمَ بِها أَهْلُ الأَرْضِ جَميعًا، لا فَرْقَ بَيْنَهُمْ، وَإِنِ اخْتَلَفَتْ أَلْوانُهُمْ وَأَلْسِنَتُهُمْ وَأَوْطانُهُمْ.", "This is Islam, calling to equality and justice in dealing. These are the Muslims who applied its principles sincerely; though differing in colours, languages and homelands, all the people of the earth were blessed by these principles without distinction among them.", "m57-12"]]] },
 { t: "dy", ar: "أَوَّلًا: الاسْتيعابُ — تَدْريبٌ (١): ضَعْ عَلامَةَ (✓) أَوْ (✗)، ثُمَّ صَحِّحِ الخَطَأَ", ogeler: [
  ["الإِسْلامُ أَوَّلُ مَنْ قَرَّرَ مَبْدَأَ المُساواةِ في العالَمِ.", true, "", "Islam is the first to lay down the principle of equality in the world.", "In the text: Islam preceded the advocates of principles of the modern age in this."],
  ["نَفَّذَتْ هَيْئَةُ الأُمَمِ المُتَّحِدَةِ كُلَّ ما قَرَّرَتْهُ مِنْ مَبادِئَ.", false, "لَمْ يُنَفَّذْ مِنْ مَبادِئِها إِلّا القَليلُ بِحَسَبِ ما تُريدُ الأُمَمُ القَوِيَّةُ.", "The UN applied all the principles it laid down."],
  ["التَّكاليفُ الشَّرْعِيَّةُ خاصَّةٌ يُؤَدّيها بَعْضُ المُسْلِمينَ.", false, "التَّكاليفُ الشَّرْعِيَّةُ عامَّةٌ يُطالَبُ كُلُّ مُسْلِمٍ بِأَدائِها.", "Sharia obligations are special; some Muslims perform them."],
  ["مِنْ صُوَرِ المُساواةِ في الإِسْلامِ تَنْفيذُ الحُدودِ عَلى الجَميعِ.", true, "", "The application of the prescribed punishments to everyone is among the examples of equality in Islam."],
  ["كانَتِ الأُمَمُ السّابِقَةُ تُنَفِّذُ الحُدودَ عَلى الشَّريفِ وَالضَّعيفِ.", false, "كانَتْ تُنَفِّذُها عَلى الضَّعيفِ (العامَّةِ) فَحَسْبُ.", "Earlier nations used to apply the prescribed punishments to both the noble and the weak."],
  ["جاءَ رَجُلٌ يَشْكو عُمَرَ بْنَ الخَطّابِ فَضَرَبَهُ بِالدِّرَّةِ.", false, "جاءَ رَجُلٌ يَشْكو إِلى عُمَرَ، فَضَرَبَهُ عُمَرُ بِالدِّرَّةِ.", "A man came to complain of ʿUmar, and ʿUmar struck him with a whip.", "The man had come not to complain of ʿUmar but to complain to ʿUmar (of someone else)."],
  ["قَبِلَ الرَّسولُ ﷺ شَفاعَةَ أُسامَةَ بْنِ زَيْدٍ.", false, "غَضِبَ الرَّسولُ ﷺ وَلَمْ يَقْبَلْ شَفاعَتَهُ.", "The Messenger ﷺ accepted Usāma's intercession."],
  ["يَظْهَرُ في الصَّلاةِ مَبْدَأٌ مِنْ مَبادِئِ المُساواةِ.", true, "", "One of the principles of equality is visible in prayer."],
  ["تَقْريرُ مَبْدَأِ المُساواةِ في الإِسْلامِ شَمِلَ الجانِبَيْنِ النَّظَرِيَّ وَالعَمَلِيَّ.", true, "", "The principle of equality in Islam covered both the theoretical and the practical side."]] },
 { t: "esle", ar: "تَدْريبٌ (٢): وائِمْ بَيْنَ العِباراتِ المَوْجودَةِ في القائِمَةِ (أ)، وَما يُناسِبُها مِنَ القائِمَةِ (ب)", ciftler: [
  ["عَلِيُّ بْنُ أَبي طالِبٍ وَالخَصْمُ.", "قَبَّلَ عُمَرُ عَلِيًّا بَعْدَ أَنْ حَكَمَ بَيْنَهُ وَبَيْنَ خَصْمِهِ.", "ʿAlī and his opponent"], ["أُسامَةُ بْنُ زَيْدٍ.", "المَخْزومِيَّةُ الَّتي سَرَقَتْ.", "Usāma ibn Zayd"], ["عِنْدَما وَلِيَ أَبو بَكْرٍ الخِلافَةَ.", "وُلّيتُ عَلَيْكُمْ وَلَسْتُ بِخَيْرِكُمْ.", "When Abū Bakr became caliph"],
  ["طَلَبَ تَنْفيذَ القِصاصِ في نَفْسِهِ.", "عُمَرُ بْنُ الخَطّابِ وَالدِّرَّةُ.", "He asked that retribution be applied to him"], ["الدُّوَلُ الكُبْرى قَبْلَ الإِسْلامِ.", "تُنَفَّذُ القَوانينُ عَلى العامَّةِ فَحَسْبُ.", "The great states before Islam"], ["الصَّلاةُ وَالحَجُّ في الإِسْلامِ.", "مِنْ صُوَرِ المُساواةِ عِنْدَ المُسْلِمينَ.", "Prayer and Hajj in Islam"]] }
]},
// ---------------- DERS 58 ----------------
{ no: 58, kisa: "اسْتيعابٌ وَمُفْرَداتٌ", ar: "اسْتيعابٌ وَمُفْرَداتٌ وَتَعْبيراتٌ", tr: "Comprehension, words and expressions", ozet: "Paragraph ideas, short answers, singulars, compounds, antonyms, set phrases.", bloklar: [
 { t: "esle", ar: "تَدْريبٌ (٣): وائِمْ بَيْنَ الفِكْرَةِ في (أ) وَرَقْمِ الفِقْرَةِ في (ب)", ciftler: [
  ["الإِسْلامُ أَوَّلُ مَنْ دَعا إِلى مَبْدَأِ المُساواةِ.", "الفِقْرَةُ (١)", "Islam is the first to call to equality."], ["الإِسْلامُ يُطَبِّقُ المُساواةَ فِعْلًا، وَالآخَرونَ يُنَفِّذونَ قَليلًا مِنْها.", "الفِقْرَةُ (٢)", "Islam applies equality in practice; others apply little of it."],
  ["يَجِبُ أَداءُ التَّكاليفِ دونَ اسْتِثْناءٍ.", "الفِقْرَةُ (٣)", "Obligations must be fulfilled without exception."], ["هُناكَ رُكْنانِ في الإِسْلامِ تَظْهَرُ فيهِما المُساواةُ.", "الفِقْرَةُ (٤)", "There are two pillars in which equality is visible."],
  ["يَجِبُ أَنْ تُقامَ الحُدودُ عَلى الأَغْنِياءِ وَالفُقَراءِ.", "الفِقْرَةُ (٥)", "The prescribed punishments must be applied to the rich and the poor."], ["عُمَرُ يَطْلُبُ أَنْ يَقْتَصَّ المُسْلِمُ مِنْهُ.", "الفِقْرَةُ (٦)", "ʿUmar wants a Muslim to take retribution from him."]] },
 { t: "acik", ar: "تَدْريبٌ (٤): أَجِبْ بِاخْتِصارٍ عَمّا يَلي", aciklama: "Answer it yourself first; then look at the answer.", ogeler: [
  ["بِكَمْ سَنَةٍ سَبَقَ الإِسْلامُ الآخَرينَ في المُساواةِ؟", "سَبَقَ دُعاةَ المَبادِئِ في العَصْرِ الحَديثِ بِنَحْوِ أَرْبَعَةَ عَشَرَ قَرْنًا.", "How many years before others did Islam precede in equality?", "No number is given in the text; the answer was inferred from the period between the rise of Islam and the modern age."],
  ["اذْكُرْ أَمْثِلَةً عَلى التَّكاليفِ الشَّرْعِيَّةِ.", "الصَّلاةُ، وَالصَّوْمُ، وَالزَّكاةُ، وَالحَجُّ.", "Give examples of Sharia obligations."],
  ["لِماذا اسْتَشْفَعَ أَهْلُ المَرْأَةِ المَخْزومِيَّةِ بِأُسامَةَ؟", "لِحُبِّ الرَّسولِ ﷺ إِيّاهُ.", "Why did the family of the Makhzūmī woman make Usāma the intermediary?"],
  ["هَلْ قَبِلَ الرَّسولُ ﷺ كَلامَ أُسامَةَ؟", "لا، بَلْ غَضِبَ.", "Did the Messenger ﷺ accept Usāma's word?"],
  ["ماذا قالَ الرَّسولُ ﷺ لِأُسامَةَ؟", "«أَتَشْفَعُ في حَدٍّ مِنْ حُدودِ اللهِ؟»", "What did the Messenger ﷺ say to Usāma?"],
  ["لِماذا أَنَّبَ عُمَرُ بْنُ الخَطّابِ نَفْسَهُ كَثيرًا؟", "لِأَنَّهُ ضَرَبَ رَجُلًا جاءَ يَسْتَعينُ بِهِ عَلى دَفْعِ الظُّلْمِ، فَظَلَمَهُ.", "Why did ʿUmar rebuke himself so much?"],
  ["ما الخَطَأُ الَّذي كَرِهَهُ عَلِيٌّ في قَوْلِ عُمَرَ: «قُمْ يا أَبا الحَسَنِ فَاجْلِسْ مَعَ خَصْمِكَ»؟", "أَنَّهُ كَنّاهُ بِحَضْرَةِ خَصْمِهِ، وَالتَّكْنِيَةُ ضَرْبٌ مِنَ التَّكْريمِ، فَلَمْ يُساوِ بَيْنَهُما.", "What did ʿAlī dislike in ʿUmar's words?"],
  ["لِماذا أَنَّبَ عُمَرُ بْنُ الخَطّابِ عَمْرَو بْنَ العاصِ؟ وَماذا قالَ لَهُ؟", "لِأَنَّ ابْنَهُ اعْتَدى عَلى المِصْرِيِّ مُعْتَمِدًا عَلى سُلْطانِ أَبيهِ، وَقالَ لَهُ: «يا عَمْرُو، مَتى اسْتَعْبَدْتُمُ النّاسَ وَقَدْ وَلَدَتْهُمْ أُمَّهاتُهُمْ أَحْرارًا؟»", "Why did ʿUmar rebuke ʿAmr ibn al-ʿĀṣ, and what did he say to him?"]] },
 { t: "bosluk", ar: "ثانِيًا: المُفْرَداتُ — تَدْريبٌ (١): الكَلِماتُ الَّتي تَحْتَها خَطٌّ جُموعٌ وَرَدَتْ في النَّصِّ، اكْتُبْ مُفْرَدَ كُلٍّ مِنْها في الفَراغِ", kutu: ["وَطَنٍ", "رُكْنٍ", "صَفًّا… صَفٍّ", "حَدٍّ", "لَوْنٍ", "دَرَجَةُ", "أُمُّ", "الأُمَّةُ"], ogeler: [
  ["كُلُّ ___ مِنْ [[أَوْطانِ]] المُسْلِمينَ هُوَ بَلَدي.", "وَطَنٍ", null, "Of the Muslims' homelands, every homeland is my country."],
  ["يُطَبِّقُ المُسْلِمُ كُلَّ ___ مِنْ [[أَرْكانِ]] الإِسْلامِ الخَمْسَةِ.", "رُكْنٍ", null, "The Muslim performs every pillar of the five pillars of Islam."],
  ["يَقِفُ المُسْلِمونَ في الصَّلاةِ [[صُفوفًا]]؛ ___ بَعْدَ ___.", "صَفًّا… صَفٍّ", null, "Muslims stand in rows in prayer; row after row."],
  ["لا يَشْفَعُ المُؤْمِنُ في ___ مِنْ [[حُدودِ]] اللهِ.", "حَدٍّ", null, "The believer does not intercede in one of God's prescribed punishments."],
  ["انْظُرْ إِلى هذِهِ [[الأَلْوانِ]]، أَيُّ ___ مِنْها أَجْمَلُ؟", "لَوْنٍ", null, "Look at these colours, which colour is more beautiful?"],
  ["كانَتْ ___ الحَرارَةِ اليَوْمَ عَشْرَ [[دَرَجاتٍ]].", "دَرَجَةُ", null, "Today the temperature was ten degrees."],
  ["خَديجَةُ ___ المُؤْمِنينَ، هِيَ أولى [[أُمَّهاتِ]] المُؤْمِنينَ.", "أُمُّ", null, "Khadīja, mother of the believers, is the first of the mothers of the believers."],
  ["___ الإِسْلامِيَّةُ خَيْرُ [[الأُمَمِ]] الَّتي أُخْرِجَتْ لِلنّاسِ.", "الأُمَّةُ", null, "The Islamic community is the best of the communities brought out for people."]] },
 { t: "esle", ar: "تَدْريبٌ (٢): وائِمْ بَيْنَ الكَلِماتِ في القائِمَةِ (أ)، وَما يُناسِبُها في القائِمَةِ (ب)", aciklama: "Then use each compound in your own sentence.", ciftler: [
  ["مَبْدَأُ", "المُساواةِ", "the principle of equality"], ["دُعاةُ", "المَبادِئِ", "the advocates of principles"], ["هَيْئَةُ", "الأُمَمِ", "the United Nations"], ["المُجْتَمَعُ", "الإِسْلامِيُّ", "Islamic society"], ["دَفْعُ", "الظُّلْمِ", "warding off injustice"],
  ["التَّكاليفُ", "الشَّرْعِيَّةُ", "Sharia obligations"], ["دونَ", "اسْتِثْناءٍ", "without exception"], ["حُدودُ", "اللهِ", "God's prescribed punishments"], ["يَوْمُ", "القِيامَةِ", "the Day of Resurrection"], ["أَهْلُ", "الأَرْضِ", "the people of the earth"]] },
 { t: "acik", ar: "تَدْريبٌ (٣): هاتِ مِنَ النَّصِّ كَلِماتٍ مُضادَّةً في المَعْنى لِما تَحْتَهُ خَطٌّ", aciklama: "Find it yourself first; then look at the answer.", ogeler: [
  ["في العُصورِ [[القَديمَةِ]]، نَجِدُ الإِنْسانَ أَكْثَرَ مُحافَظَةً عَلى البيئَةِ.", "الحَديثَةِ", "old ↔ modern"],
  ["حَديثُ الدُّوَلِ الكُبْرى عَنِ المُساواةِ لَيْسَ [[عَمَلِيًّا]].", "نَظَرِيًّا", "practical ↔ theoretical"],
  ["[[قَليلٌ]] مِنَ الدُّوَلِ يُطَبِّقُ مَبْدَأَ المُساواةِ.", "كَثيرٌ", "little ↔ much"],
  ["لِقاؤُنا [[غَدًا]] إِنْ شاءَ اللهُ.", "أَمْسِ / اليَوْمَ", "tomorrow ↔ yesterday", "‘أَمْس’ does not occur in the text; ‘غَدًا’ and ‘اليَوْمَ’ are in the text."],
  ["لا يُفَرِّقُ الإِسْلامُ بَيْنَ [[العامَّةِ]] وَغَيْرِهِمْ.", "الشَّريفِ (الخاصَّةِ)", "common people ↔ elite", "In the text ‘الشَّريف’ occurs as the counterpart of ‘العامَّة’."],
  ["الجَوادُ [[الأَبْيَضُ]] حازَ الجائِزَةَ.", "الأَسْوَدُ", "white ↔ black"],
  ["يَنْبَغي أَنْ [[تَعْدِلَ]] بَيْنَ الجَميعِ.", "تَظْلِمَ", "to act justly ↔ to wrong"],
  ["مَتى تَكونُ [[فارِغًا]] يا صَديقي؟", "مَشْغولًا", "empty ↔ busy"],
  ["لَسْتُ [[سَعيدًا]] اليَوْمَ.", "حَزينًا", "happy ↔ sad"],
  ["هذا رَجُلٌ [[وَضيعٌ]].", "شَريفٌ", "low ↔ noble"]] },
 { t: "acik", ar: "تَدْريبٌ (٤): اقْرَأِ الجُمَلَ التّالِيَةَ، ثُمَّ انْسُجْ عَلى مِنْوالِها", aciklama: "First write it yourself; then look at the sample sentence.", ogeler: [
  ["تُنَفَّذُ الحُدودُ عَلى الجَميعِ بِلا اسْتِثْناءٍ. (أ) … القَوانينُ …", "تُطَبَّقُ القَوانينُ عَلى الجَميعِ بِلا اسْتِثْناءٍ.", "The laws are applied to everyone without exception."],
  ["(ب) … جَميعُ الغُرَفِ …", "تُنَظَّفُ جَميعُ الغُرَفِ بِلا اسْتِثْناءٍ.", "All the rooms are cleaned without exception."],
  ["ظَلَّ يُحاسِبُ نَفْسَهُ، حَتّى أَشْفَقَ عَلَيْهِ النّاسُ. (أ) … يُؤَنِّبُ …", "ظَلَّ يُؤَنِّبُ نَفْسَهُ، حَتّى أَشْفَقَ عَلَيْهِ النّاسُ.", "He rebuked himself until people felt pity for him."],
  ["(ب) … كَرِهَهُ النّاسُ.", "ظَلَّ يَظْلِمُ النّاسَ، حَتّى كَرِهَهُ النّاسُ.", "He continued to wrong until people came to hate him."],
  ["(ج) … يَعْدِلُ … النّاسُ.", "ظَلَّ يَعْدِلُ بَيْنَ النّاسِ، حَتّى أَحَبَّهُ النّاسُ.", "He acted justly until people loved him."],
  ["أَنَّبَ نَفْسَهُ هذا التَّأْنيبَ خَشْيَةَ اللهِ تَعالى. (أ) حاسَبَ …", "حاسَبَ نَفْسَهُ هذا الحِسابَ خَشْيَةَ اللهِ.", "Out of fear of God he called himself to account thus."],
  ["(ب) حَفِظَ …", "حَفِظَ القُرْآنَ هذا الحِفْظَ رَغْبَةً في الأَجْرِ.", "Out of desire for reward he memorized the Qur'an thus."],
  ["(ج) رَبّى …", "رَبّى أَوْلادَهُ هذِهِ التَّرْبِيَةَ حُبًّا لَهُمْ.", "Out of his love he brought up his children thus."],
  ["(د) سَعى بِنَفْسِهِ …", "سَعى بِنَفْسِهِ هذا السَّعْيَ طَلَبًا لِلرِّزْقِ.", "For provision he strove thus himself."]] }
]},
// ---------------- DERS 59 ----------------
{ no: 59, kisa: "المَفْعولُ المُطْلَقُ", ar: "قَواعِدُ اللُّغَةِ (أ): المَفْعولُ المُطْلَقُ", tr: "Grammar: the absolute object (mafʿūl muṭlaq)", ozet: "The accusative verbal noun that comes from the very wording of the verb to emphasize the verb, or to show its kind or number; substitutes: kull, baʿḍ and numbers.", bloklar: [
 { t: "tablo", ar: "الأَمْثِلَةُ: ادْرُسْ وَتَأَمَّلْ", bas: ["", "الأَمْثِلَةُ"], satir: [
  ["أ", "﴿وَمَا بَدَّلُوا [[تَبْدِيلًا]]﴾ ﴿وَكَلَّمَ اللَّهُ مُوسَىٰ [[تَكْلِيمًا]]﴾ ﴿يَوْمَ تَمُورُ السَّمَاءُ [[مَوْرًا]] * وَتَسِيرُ الْجِبَالُ [[سَيْرًا]]﴾"],
  ["ب", "﴿فَأَخَذْنَاهُمْ [[أَخْذَ]] عَزِيزٍ مُقْتَدِرٍ﴾ ﴿وَتَأْكُلُونَ التُّرَاثَ [[أَكْلًا]] لَمًّا * وَتُحِبُّونَ الْمَالَ [[حُبًّا]] جَمًّا﴾ جَلَسَ الطّالِبُ [[جُلوسَ]] العُلَماءِ."],
  ["ج", "﴿وَحُمِلَتِ الْأَرْضُ وَالْجِبَالُ فَدُكَّتَا [[دَكَّةً]] وَاحِدَةً﴾ ﴿مَنْ يَأْتِ مِنْكُنَّ بِفَاحِشَةٍ مُبَيِّنَةٍ يُضَاعَفْ لَهَا الْعَذَابُ [[ضِعْفَيْنِ]]﴾ صَرَخَ الطِّفْلُ [[صَرْخَةً]]."],
  ["د", "﴿فَلَا تَمِيلُوا [[كُلَّ]] الْمَيْلِ﴾ ﴿وَلَوْ تَقَوَّلَ عَلَيْنَا [[بَعْضَ]] الْأَقَاوِيلِ﴾ ﴿فَاجْلِدُوهُمْ [[ثَمَانِينَ]] جَلْدَةً﴾"]] },
 { t: "kural", ar: "الشَّرْحُ", metin: "تَأَمَّلْ ما تَحْتَهُ خَطٌّ في الأَمْثِلَةِ (أ، ب، ج) تَجِدْ أَنَّها مَصادِرُ مِنْ أَلْفاظِ الأَفْعالِ الَّتي قَبْلَها، وَتَأَمَّلْ كَيْفَ أَنَّها مَنْصوبَةٌ، وَهذا النَّوْعُ مِنَ المَصادِرِ يُسَمّى «المَفْعولَ المُطْلَقَ». في أَمْثِلَةِ (أ) جاءَ المَفْعولُ المُطْلَقُ لِمُجَرَّدِ تَوْكيدِ الفِعْلِ قَبْلَهُ، أَمّا في (ب) فَقَدْ بَيَّنَ نَوْعَ الفِعْلِ، وَفي (ج) بَيَّنَ عَدَدَهُ. وَفي (د) أُضيفَتْ (كُلّ) وَ(بَعْض) وَأَلْفاظُ العَدَدِ إِلى المَصْدَرِ وَلَيْسَتْ بِمَصْدَرٍ، وَلكِنَّها تُعْرَبُ نائِبَةً عَنِ المَفْعولِ المُطْلَقِ.", tr: "The underlined words in (أ، ب، ج) are accusative verbal nouns from the wording of the verbs before them: the absolute object. In (أ) it only emphasizes the verb, in (ب) it shows its kind, in (ج) its number. In (د) كُلّ، بَعْض and number words are annexed to the verbal noun; they are not verbal nouns but are parsed as substituting for the absolute object." },
 { t: "kural", ar: "القاعِدَةُ", metin: "المَفْعولُ المُطْلَقُ: مَصْدَرٌ مَنْصوبٌ مِنْ لَفْظِ الفِعْلِ، يُذْكَرُ لِتَأْكيدِ الفِعْلِ، وَما يَعْمَلُ عَمَلَهُ، أَوْ لِبَيانِ نَوْعِهِ، أَوْ لِبَيانِ عَدَدِهِ. وَهُناكَ كَلِماتٌ مَنْصوبَةٌ تُضافُ إِلى المَصْدَرِ وَلَيْسَتْ بِمَصْدَرٍ، وَمِنْها: (كُلّ) وَ(بَعْض) وَالعَدَدُ، وَتُعْرَبُ نائِبَةً عَنِ المَفْعولِ المُطْلَقِ.", tr: "The absolute object: the accusative verbal noun that comes from the wording of the verb (or of what works like it), said to emphasize the verb, to show its kind or its number. Words annexed to the verbal noun such as كُلّ، بَعْض and numbers substitute for the absolute object." },
 { t: "acik", ar: "تَدْريبٌ (١): اسْتَخْرِجِ المَفْعولَ المُطْلَقَ، وَبَيِّنْ نَوْعَهُ فيما يَلي", aciklama: "First find it yourself; then look at the answer (absolute object — its kind).", ogeler: [
  ["﴿يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا﴾", "تَسْليمًا — مُؤَكِّدٌ لِلْفِعْلِ", "Invoke blessings and peace upon him."], ["﴿فَعَصَىٰ فِرْعَوْنُ الرَّسُولَ فَأَخَذْنَاهُ أَخْذًا وَبِيلًا﴾", "أَخْذًا — مُبَيِّنٌ لِلنَّوْعِ (مَوْصوفٌ)", "We seized him with a mighty seizing."],
  ["﴿وَنُفِخَ فِي الصُّورِ فَجَمَعْنَاهُمْ جَمْعًا﴾", "جَمْعًا — مُؤَكِّدٌ", "We gathered them all together."], ["﴿وَقُولُوا قَوْلًا سَدِيدًا﴾", "قَوْلًا — مُبَيِّنٌ لِلنَّوْعِ", "Speak true words."],
  ["﴿وَتَظُنُّونَ بِاللَّهِ الظُّنُونَا﴾", "الظُّنونا — مُبَيِّنٌ لِلنَّوْعِ (مُعَرَّفٌ بِـ«ال»)", "You were thinking various thoughts about God."], ["﴿وَتَبَتَّلْ إِلَيْهِ تَبْتِيلًا﴾", "تَبْتيلًا — مُؤَكِّدٌ", "Turn to Him wholly."],
  ["﴿لَنُحَرِّقَنَّهُ ثُمَّ لَنَنْسِفَنَّهُ فِي الْيَمِّ نَسْفًا﴾", "نَسْفًا — مُؤَكِّدٌ", "We will burn it, then scatter it in the sea."], ["﴿وَاللَّهُ أَنْبَتَكُمْ مِنَ الْأَرْضِ نَبَاتًا﴾", "نَباتًا — مُؤَكِّدٌ (اسْمُ مَصْدَرٍ)", "God caused you to grow from the earth like a plant."],
  ["﴿فَإِذَا نُفِخَ فِي الصُّورِ نَفْخَةٌ وَاحِدَةٌ﴾", "نَفْخَةٌ — مُبَيِّنٌ لِلْعَدَدِ (نائِبُ فاعِلٍ هُنا لِأَنَّ الفِعْلَ مَبْنِيٌّ لِلْمَجْهولِ)", "When the Trumpet is blown with one blast.", "Here نَفْخَةٌ is nominative: it is the deputy agent of the passive verb; in meaning it is a verbal noun indicating number."],
  ["﴿فَحَاسَبْنَاهَا حِسَابًا شَدِيدًا وَعَذَّبْنَاهَا عَذَابًا نُكْرًا﴾", "حِسابًا، عَذابًا — مُبَيِّنانِ لِلنَّوْعِ", "We called him to account with a severe reckoning and punished him with a terrible punishment."], ["﴿وَكَلَّمَ اللَّهُ مُوسَىٰ تَكْلِيمًا﴾", "تَكْليمًا — مُؤَكِّدٌ", "God truly spoke to Moses."],
  ["﴿وَيُرِيدُ الشَّيْطَانُ أَنْ يُضِلَّهُمْ ضَلَالًا بَعِيدًا﴾", "ضَلالًا — مُبَيِّنٌ لِلنَّوْعِ", "Satan wishes to lead them far astray.", "ضَلالًا is not the verbal noun of the verb أَضَلَّ but of ضَلَّ; but since it is from the same root it is counted as the absolute object."]] },
 { t: "acik", ar: "تَدْريبٌ (٢): ضَعْ خَطًّا تَحْتَ المَفْعولِ المُطْلَقِ فيما يَلي", aciklama: "Find it yourself first; then look at the answer.", ogeler: [
  ["﴿وَمَنْ يُشْرِكْ بِاللَّهِ فَقَدْ ضَلَّ ضَلَالًا بَعِيدًا﴾", "ضَلالًا", "Whoever associates others with God has gone far astray."], ["﴿يَا أَيُّهَا الْإِنْسَانُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدْحًا فَمُلَاقِيهِ﴾", "كَدْحًا (عامِلُهُ اسْمُ الفاعِلِ كادِحٌ)", "O man, you are striving toward your Lord with great exertion."],
  ["﴿إِذَا زُلْزِلَتِ الْأَرْضُ زِلْزَالَهَا﴾", "زِلْزالَها", "When the earth is shaken with its violent shaking."], ["﴿فَاصْبِرْ صَبْرًا جَمِيلًا﴾", "صَبْرًا", "Be patient with a beautiful patience."],
  ["﴿وَيَدْرَأُ عَنْهَا الْعَذَابَ أَنْ تَشْهَدَ أَرْبَعَ شَهَادَاتٍ بِاللَّهِ إِنَّهُ لَمِنَ الْكَاذِبِينَ﴾", "أَرْبَعَ (نائِبٌ عَنِ المَفْعولِ المُطْلَقِ)", "The woman's testifying four times by God that her husband is a liar…"], ["تَلا القارِئُ القُرْآنَ تِلاوَةً مُجَوَّدَةً.", "تِلاوَةً", "The reciter recited the Qur'an with tajwīd."],
  ["أَحاطَ السِّوارُ بِالمِعْصَمِ إِحاطَةً.", "إِحاطَةً", "The bracelet encircled the wrist."], ["نَسَخْتُ الخَطَّ عِشْرينَ نُسْخَةً.", "عِشْرينَ (نائِبٌ عَنِ المَفْعولِ المُطْلَقِ)", "I multiplied the writing in twenty copies."],
  ["لا تَمْدَحِ الرَّجُلَ كُلَّ المَدْحِ فَتُتَّهَمَ بِالمُداهَنَةِ.", "كُلَّ (نائِبٌ عَنِ المَفْعولِ المُطْلَقِ)", "Do not overpraise the man, or you will be accused of flattery."], ["طَرَقَ البابَ طَرْقَتَيْنِ، فَلَمْ يُفْتَحْ لَهُ.", "طَرْقَتَيْنِ", "He knocked on the door twice, it was not opened."]] },
 { t: "bosluk", ar: "تَدْريبٌ (٣): امْلَأِ الفَراغَ بِالمَفْعولِ المُطْلَقِ المُناسِبِ مِمّا بَيْنَ القَوْسَيْنِ", ogeler: [
  ["انْتَقَمَ المَظْلومُ مِنَ الظّالِمِ ___.", "انْتِقامًا", ["مُنْتَقِمٌ", "ناقِمًا"], "The wronged took revenge on the wrongdoer."],
  ["أَكْرَمَ الرَّجُلُ ضَيْفَهُ ___ عَظيمًا.", "إِكْرامًا", ["كَريمًا", "تَكْريمٌ"], "The man showed his guest great hospitality."],
  ["تَقَدَّمَ الطّالِبُ في دِراسَتِهِ ___ مَلْحوظًا.", "تَقَدُّمًا", ["مِقْدامًا", "قادِمًا"], "The student made visible progress in his lessons."],
  ["اسْتَدْرَجَ اللِّصُّ فَريسَتَهُ ___.", "اسْتِدْراجًا", ["دارِجًا", "مُسْتَدْرِجًا"], "The thief lured his prey step by step into the trap."],
  ["جَلَسَ المُتْعَبُ ___ المَريضِ.", "جُلوسَ", ["جالِسًا", "إِجْلاسًا"], "The tired man sat like a sick man."],
  ["خَطا الرَّضيعُ في الغُرْفَةِ ___.", "خُطْوَتَيْنِ", ["خُطْوَتانِ", "خُطْوَةٌ"], "The baby took two steps in the room."]] },
 { t: "acik", ar: "تَدْريبٌ (٤): اسْتَعْمِلِ الكَلِماتِ التّالِيَةَ في جُمَلٍ مُفيدَةٍ بِحَيْثُ تَكونُ نائِبَةً عَنِ المَفْعولِ المُطْلَقِ", aciklama: "Write it yourself first; then look at the example.", ogeler: [
  ["كُلّ", "أُحِبُّ والِدَيَّ كُلَّ الحُبِّ.", "all"], ["بَعْض", "اسْتَرَحْتُ بَعْضَ الرّاحَةِ.", "a little"], ["سَبْع", "طافَ الحاجُّ بِالكَعْبَةِ سَبْعَ طَوْفاتٍ.", "seven"]] },
 { t: "acik", ar: "تَدْريبٌ (٥): اجْعَلِ الكَلِماتِ التّالِيَةَ مَفْعولًا مُطْلَقًا مُؤَكِّدًا مَرَّةً، وَمُبَيِّنًا لِلنَّوْعِ أُخْرى، وَمُبَيِّنًا لِلْعَدَدِ ثالِثَةً في جُمَلٍ مِنْ إِنْشائِكَ", aciklama: "Write it yourself first; then look at the example.", ogeler: [
  ["جِلْسَة (جُلوس)", "مُؤَكِّدٌ: جَلَسْتُ جُلوسًا. — نَوْعٌ: جَلَسْتُ جِلْسَةَ الطّالِبِ المُؤَدَّبِ. — عَدَدٌ: جَلَسْتُ جِلْسَتَيْنِ.", "sitting"],
  ["نُهوض", "مُؤَكِّدٌ: نَهَضَ الشَّعْبُ نُهوضًا. — نَوْعٌ: نَهَضَتِ الأُمَّةُ نُهوضًا عَظيمًا. — عَدَدٌ: نَهَضَ المَريضُ نَهْضَتَيْنِ ثُمَّ جَلَسَ.", "rising"],
  ["انْتِصاب", "مُؤَكِّدٌ: انْتَصَبَ الجُنْدِيُّ انْتِصابًا. — نَوْعٌ: انْتَصَبَ انْتِصابَ الجَبَلِ. — عَدَدٌ: انْتَصَبَ انْتِصابَةً واحِدَةً.", "standing"],
  ["رُجوع", "مُؤَكِّدٌ: رَجَعْتُ رُجوعًا. — نَوْعٌ: رَجَعَ رُجوعَ المُنْتَصِرِ. — عَدَدٌ: رَجَعَ رَجْعَتَيْنِ.", "returning"]] }
]},
// ---------------- DERS 60 ----------------
{ no: 60, kisa: "فَهْمُ المَسْموعِ", ar: "فَهْمُ المَسْموعِ", tr: "Listening", ozet: "Equality in judgment: ʿUmar and Ubayy, the Egyptian and ʿAmr's son — a listening text in two parts.", bloklar: [
 { t: "dinle", s: "l60a", ar: "القِسْمُ الأَوَّلُ: المُساواةُ الحَقَّةُ", aciklama: "Ubayy ibn Kaʿb and ʿUmar turn to Zayd ibn Thābit as arbitrator. Listen first, then answer the questions.", metin: [
  ["قالَ أُبَيُّ بْنُ كَعْبٍ لِعُمَرَ بْنِ الخَطّابِ - رَضِيَ اللهُ عَنْهُما -: يا أَميرَ المُؤْمِنينَ، أَنْصِفْني مِنْ نَفْسِكَ، وَاجْعَلْ بَيْني وَبَيْنَكَ حَكَمًا. قالَ عُمَرُ بْنُ الخَطّابِ - رَضِيَ اللهُ عَنْهُ -: بَيْني وَبَيْنَكَ زَيْدُ بْنُ ثابِتٍ. فَانْطَلَقَ أُبَيٌّ وَعُمَرُ إِلى زَيْدٍ.", "Ubayy ibn Kaʿb said to ʿUmar ibn al-Khaṭṭāb (may God be pleased with them both): “O Commander of the Faithful, give me my right against yourself; put an arbitrator between you and me.” ʿUmar said, “Let Zayd ibn Thābit be between you and me.” Ubayy and ʿUmar went to Zayd."],
  ["وَعِنْدَما وَصَلا إِلى مَجْلِسِ زَيْدٍ أَشارَ زَيْدٌ إِلى عُمَرَ لِيَجْلِسَ في مَكانٍ يُناسِبُ الخَليفَةَ، وَأَعْطاهُ وِسادَةً لِيَسْتَنِدَ إِلَيْها. قالَ عُمَرُ لِزَيْدٍ: بَدَأْتَ بِالظُّلْمِ يا زَيْدُ، لَقَدْ حَضَرْنا إِلَيْكَ لِتَقْضِيَ بَيْنَنا. هُنا أَشارَ زَيْدٌ إِلى المَكانِ أَمامَهُ وَقالَ: إِذَنْ هاهُنا يا أَميرَ المُؤْمِنينَ. جَلَسَ أُبَيٌّ وَعُمَرُ أَمامَ زَيْدٍ.", "When they reached Zayd's assembly, Zayd gestured to ʿUmar to sit in a place befitting the caliph and gave him a cushion to lean on. ʿUmar said to Zayd, “You began with injustice, O Zayd! We came to you for you to judge between us.” Then Zayd pointed to the place before him and said, “Then here, O Commander of the Faithful.” Ubayy and ʿUmar sat before Zayd."],
  ["اسْتَمَعَ زَيْدٌ إِلى شَكْوى أُبَيِّ بْنِ كَعْبٍ في قِطْعَةِ أَرْضٍ، فَلَمّا انْتَهى مِنْ عَرْضِ قَضِيَّتِهِ قالَ لَهُ زَيْدٌ: أُريدُ شاهِدَيْنِ عَدْلَيْنِ. قالَ أُبَيٌّ: لَيْسَ عِنْدي شاهِدانِ. قالَ زَيْدٌ لِأُبَيٍّ: أَعْفِ أَميرَ المُؤْمِنينَ مِنْ حَلِفِ اليَمينِ.", "Zayd heard Ubayy ibn Kaʿb's complaint about a piece of land. When he finished telling his case, Zayd said to him, “I want two just witnesses.” Ubayy said, “I do not have two witnesses.” Zayd said to Ubayy, “Excuse the Commander of the Faithful from taking an oath.”"],
  ["سَأَلَ عُمَرُ زَيْدًا: أَهكَذا تَقْضي بَيْنَ النّاسِ كُلِّهِمْ؟ قالَ زَيْدٌ: لا. قالَ عُمَرُ: فَاقْضِ بَيْنَنا كَما تَقْضي بَيْنَ النّاسِ؛ يَجِبُ أَنْ يَكونَ أَميرُ المُؤْمِنينَ وَعامَّةُ النّاسِ عِنْدَكَ سَواءً. قالَ زَيْدٌ: إِذَنِ احْلِفْ يا أَميرَ المُؤْمِنينَ. فَحَلَفَ عُمَرُ قائِلًا: وَاللهِ الَّذي لا إِلهَ إِلّا هُوَ لَيْسَ لِأُبَيٍّ حَقٌّ في هذِهِ الأَرْضِ. فَقَضى زَيْدٌ بِالأَرْضِ لِعُمَرَ - رَضِيَ اللهُ عَنْهُمْ جَميعًا -.", "ʿUmar asked Zayd, “Do you judge like this among all people?” Zayd said, “No.” ʿUmar said, “Then judge between us as you judge among people; the Commander of the Faithful and the common people must be equal with you.” Zayd said, “Then swear, O Commander of the Faithful.” ʿUmar swore: “I swear by God, other than whom there is no god, that Ubayy has no right in this land.” Zayd ruled that the land belonged to ʿUmar (may God be pleased with them all)."]],
  not: "The text was transcribed from the recording; the book contains only the questions." },
 { t: "sirala", ar: "تَدْريبٌ (١): رَتِّبِ الأَحْداثَ كَما جاءَتْ في القِصَّةِ", aciklama: "Put the events in the order of the story.", ogeler: [
  "أُبَيٌّ وَعُمَرُ يَذْهَبانِ إِلى القاضي.", "زَيْدٌ يَطْلُبُ مِنْ عُمَرَ الجُلوسَ في مَكانٍ أَفْضَلَ.", "عُمَرُ يَطْلُبُ مِنْ زَيْدٍ مُراعاةَ العَدْلِ.", "زَيْدٌ يَسْتَمِعُ إِلى شَكْوى أُبَيٍّ.", "عُمَرُ يَحْلِفُ أَمامَ زَيْدٍ."],
  not: "ʿUmar asks for justice twice: in the place of sitting (‘You began with injustice’) and in the matter of the oath; here the first was taken as the basis." },
 { t: "acik", ar: "تَدْريبٌ (٢): أَجِبْ مِمّا سَمِعْتَ عَنِ الأَسْئِلَةِ التّالِيَةِ بِاخْتِصارٍ", aciklama: "Answer it yourself first; then look at the answer.", ogeler: [
  ["لِماذا قالَ عُمَرُ لِزَيْدٍ: بَدَأْتَ بِالظُّلْمِ؟", "لِأَنَّ زَيْدًا أَرادَ أَنْ يُجْلِسَهُ في مَكانٍ يُناسِبُ الخَليفَةَ وَأَعْطاهُ وِسادَةً، فَمَيَّزَهُ عَلى خَصْمِهِ.", "Why did ʿUmar say to Zayd ‘You began with injustice’?"],
  ["ما مَوْضوعُ الخِلافِ بَيْنَ أُبَيٍّ وَعُمَرَ؟", "قِطْعَةُ أَرْضٍ.", "What was the subject of the dispute between Ubayy and ʿUmar?"],
  ["لِماذا طَلَبَ زَيْدٌ مِنْ أُبَيٍّ أَنْ يُعْفِيَ عُمَرَ مِنَ الحَلِفِ؟", "إِكْرامًا لِأَميرِ المُؤْمِنينَ وَتَوْقيرًا لَهُ.", "Why did Zayd ask Ubayy to excuse ʿUmar from the oath?", "The reason is not stated explicitly in the recording; it is understood to be out of respect for the caliph."],
  ["ماذا يَجِبُ عَلى المُدَّعي؟", "أَنْ يَأْتِيَ بِشاهِدَيْنِ عَدْلَيْنِ (البَيِّنَةِ).", "What falls on the claimant?"],
  ["ماذا يَجِبُ عَلى المُنْكِرِ؟", "أَنْ يَحْلِفَ اليَمينَ.", "What falls on the one who denies?"]] },
 { t: "secim", ar: "تَدْريبٌ (٣): اخْتَرِ الجَوابَ الصَّحيحَ", ogeler: [
  ["صاحِبُ الشَّكْوى هُوَ…", "أُبَيٌّ", ["عُمَرُ", "زَيْدٌ"], "The complainant …"],
  ["جَلَسَ عُمَرُ…", "بِجانِبِ أُبَيٍّ", ["بِجانِبِ زَيْدٍ", "أَمامَ أُبَيٍّ"], "ʿUmar sat …", "In the recording: Ubayy and ʿUmar sat before Zayd (side by side)."],
  ["كانَ القاضي هُوَ…", "زَيْدٌ", ["عُمَرُ", "أُبَيٌّ"], "The judge was …"]] },
 { t: "dinle", s: "l60b", ar: "القِسْمُ الثّاني: مِنْ صُوَرِ العَدْلِ في الإِسْلامِ", aciklama: "An Egyptian man complains to ʿUmar of ʿAmr ibn al-ʿĀṣ's son. Listen first, then answer the questions.", metin: [
  ["بَيْنَما كانَ أَميرُ المُؤْمِنينَ عُمَرُ بْنُ الخَطّابِ في مَجْلِسِهِ، وَقَفَ رَجُلٌ مِنْ أَهْلِ مِصْرَ قائِلًا: يا أَميرَ المُؤْمِنينَ، جِئْتُكَ مِنْ مِصْرَ أَطْلُبُ عَدْلَكَ. قالَ عُمَرُ: أَهْلًا وَمَرْحَبًا، ما أَمْرُكَ؟ قالَ المِصْرِيُّ: سابَقْتُ ابْنَ الأَميرِ عَمْرِو بْنِ العاصِ، فَلَمّا سَبَقْتُهُ ضَرَبَني بِسَوْطِهِ قائِلًا: خُذْها وَأَنا ابْنُ الأَكْرَمينَ.", "When the Commander of the Faithful ʿUmar ibn al-Khaṭṭāb was in his assembly, an Egyptian man stood up and said: “O Commander of the Faithful, I have come to you from Egypt to ask your justice.” ʿUmar said, “Welcome; what is your trouble?” The Egyptian said: “I raced with the son of the emir ʿAmr ibn al-ʿĀṣ; when I passed him he struck me with his whip and said, ‘Take that, I am the son of the nobles!’”"],
  ["أَرْسَلَ عُمَرُ بْنُ الخَطّابِ رِسالَةً إِلى عَمْرِو بْنِ العاصِ قائِلًا فيها: إِذا أَتاكَ كِتابي هذا فَاشْهَدْ مَوْسِمَ الحَجِّ أَنْتَ وَابْنُكَ. ثُمَّ قالَ لِلْمِصْرِيِّ: أَقِمْ مَعَنا بِالمَدينَةِ حَتّى يَأْتِيَ عَمْرٌو وَابْنُهُ في مَوْسِمِ الحَجِّ.", "ʿUmar ibn al-Khaṭṭāb sent ʿAmr ibn al-ʿĀṣ a letter saying: “When this letter of mine reaches you, be present with your son in the Hajj season.” Then he said to the Egyptian, “Stay with us in Medina until ʿAmr and his son come in the Hajj season.”"],
  ["بَعْدَ الحَجِّ زارَ عَمْرُو بْنُ العاصِ وَابْنُهُ عُمَرَ بْنَ الخَطّابِ، وَكانَ مَعَهُ في المَجْلِسِ المِصْرِيُّ. سَأَلَ عُمَرُ ابْنَ عَمْرِو بْنِ العاصِ: لِماذا ضَرَبْتَ هذا الرَّجُلَ؟ لَمْ يُجِبِ ابْنُ عَمْرٍو، فَرَمى عُمَرُ بِالسَّوْطِ إِلى المِصْرِيِّ، وَقالَ لَهُ: اضْرِبِ ابْنَ الأَكْرَمينَ. فَأَخَذَ السَّوْطَ وَضَرَبَ ابْنَ الأَكْرَمينَ.", "After the Hajj ʿAmr ibn al-ʿĀṣ and his son visited ʿUmar ibn al-Khaṭṭāb; the Egyptian was with him in the assembly. ʿUmar asked ʿAmr's son, “Why did you strike this man?” ʿAmr's son did not answer. ʿUmar threw the whip to the Egyptian and said, “Strike the son of the nobles!” The Egyptian took the whip and struck the son of the nobles."],
  ["بَعْدَ أَنْ أَخَذَ المِصْرِيُّ حَقَّهُ، قالَ لَهُ عُمَرُ: وَالآنَ اضْرِبْ عَمْرَو بْنَ العاصِ. فَقالَ لَهُ المِصْرِيُّ: لَقَدْ ضَرَبْتُ مَنْ ضَرَبَني. ثُمَّ الْتَفَتَ عُمَرُ إِلى عَمْرٍو، وَقالَ لَهُ: مَتى اسْتَعْبَدْتُمُ النّاسَ وَقَدْ وَلَدَتْهُمْ أُمَّهاتُهُمْ أَحْرارًا؟", "After the Egyptian had received his right, ʿUmar said to him, “Now strike ʿAmr ibn al-ʿĀṣ too.” The Egyptian said, “I struck the one who struck me.” Then ʿUmar turned to ʿAmr and said, “Since when have you enslaved people when their mothers bore them free?”"]],
  not: "The text was transcribed from the recording; the book contains only the questions." },
 { t: "sirala", ar: "تَدْريبٌ (١): رَتِّبِ الأَحْداثَ كَما جاءَتْ في القِصَّةِ", aciklama: "Put the events in the order of the story.", ogeler: [
  "المِصْرِيُّ يَسْبِقُ ابْنَ عَمْرٍو.", "ابْنُ عَمْرٍو يَضْرِبُ المِصْرِيَّ.", "المِصْرِيُّ يَذْهَبُ إِلى المَدينَةِ.", "المِصْرِيُّ يَشْكو ابْنَ عَمْرٍو.", "عُمَرُ يَطْلُبُ حُضورَ عَمْرٍو وَابْنِهِ.", "عَمْرٌو وَابْنُهُ يَذْهَبانِ إِلى المَدينَةِ."] },
 { t: "acik", ar: "تَدْريبٌ (٢): أَجِبْ مِمّا سَمِعْتَ عَنِ الأَسْئِلَةِ التّالِيَةِ بِاخْتِصارٍ", aciklama: "Answer it yourself first; then look at the answer.", ogeler: [
  ["لِماذا جاءَ المِصْرِيُّ إِلى المَدينَةِ؟", "جاءَ يَطْلُبُ عَدْلَ عُمَرَ؛ لِأَنَّ ابْنَ عَمْرِو بْنِ العاصِ ضَرَبَهُ.", "Why did the Egyptian come to Medina?"],
  ["لِماذا ضَرَبَ ابْنُ عَمْرٍو المِصْرِيَّ؟", "لِأَنَّ المِصْرِيَّ سَبَقَهُ في السِّباقِ.", "Why did ʿAmr's son strike the Egyptian?"],
  ["لِماذا طَلَبَ عُمَرُ مِنَ المِصْرِيِّ ضَرْبَ ابْنِ عَمْرٍو؟", "لِيَأْخُذَ حَقَّهُ مِنْهُ قِصاصًا.", "Why did ʿUmar ask the Egyptian to strike ʿAmr's son?"],
  ["في أَيِّ مَوْسِمٍ جاءَ عَمْرٌو إِلى المَدينَةِ؟", "في مَوْسِمِ الحَجِّ.", "In which season did ʿAmr come to Medina?"],
  ["بِمَ تَصِفُ عُمَرَ بْنَ الخَطّابِ؟", "بِالعَدْلِ وَالمُساواةِ بَيْنَ النّاسِ.", "How do you describe ʿUmar ibn al-Khaṭṭāb?"]] },
 { t: "esle", ar: "تَدْريبٌ (٣): وائِمْ بَيْنَ القائِلِ في القائِمَةِ (أ) وَالقَوْلِ في القائِمَةِ (ب)", ciftler: [
  ["عُمَرُ بْنُ الخَطّابِ.", "مَتى اسْتَعْبَدْتُمُ النّاسَ؟", "ʿUmar ibn al-Khaṭṭāb"], ["المِصْرِيُّ.", "ضَرَبْتُ مَنْ ضَرَبَني.", "The Egyptian"], ["ابْنُ عَمْرِو بْنِ العاصِ.", "خُذْها وَأَنا ابْنُ الأَكْرَمينَ.", "ʿAmr ibn al-ʿĀṣ's son"]] }
]},
// ---------------- DERS 61 ----------------
{ no: 61, kisa: "التَّعْبيرُ", ar: "التَّعْبيرُ الشَّفَهِيُّ وَالكِتابِيُّ", tr: "Oral and written expression", ozet: "Discussing and writing about the ways of equality.", bloklar: [
 { t: "acik", ar: "أَوَّلًا: التَّعْبيرُ الشَّفَهِيُّ — تَدْريبٌ (١): ناقِشْ مَعَ فَريقٍ مِنْ زُمَلائِكَ الوَسائِلَ الَّتي تَتَحَقَّقُ بِها المُساواةُ في الحالاتِ التّالِيَةِ", aciklama: "A group activity; then look at the example.", ogeler: [
  ["المُساواةُ أَمامَ القانونِ.", "أَنْ يُطَبَّقَ القانونُ عَلى الجَميعِ، الوَزيرِ وَالعامِلِ، دونَ اسْتِثْناءٍ.", "equality before the law"], ["المُساواةُ في التَّعْليمِ.", "أَنْ تُفْتَحَ المَدارِسُ لِلْجَميعِ، وَأَنْ يُقْبَلَ الطّالِبُ بِحَسَبِ اجْتِهادِهِ لا بِحَسَبِ مالِهِ.", "equality in education"],
  ["المُساواةُ في العَمَلِ.", "أَنْ تُعْطى الوَظائِفُ لِلْأَكْفَأِ، وَأَنْ يَأْخُذَ كُلُّ عامِلٍ أَجْرَهُ بِحَسَبِ عَمَلِهِ.", "equality at work"], ["المُساواةُ في المُعامَلَةِ.", "أَنْ نُعامِلَ النّاسَ جَميعًا بِاحْتِرامٍ، فَقيرَهُمْ وَغَنِيَّهُمْ.", "equality in dealing"],
  ["المُساواةُ في الحُقوقِ.", "أَنْ يَنالَ كُلُّ مُواطِنٍ حَقَّهُ في العِلاجِ وَالتَّعْليمِ وَالأَمْنِ.", "equality in rights"], ["المُساواةُ في الواجِباتِ.", "أَنْ يُطالَبَ كُلُّ قادِرٍ بِأَداءِ واجِبِهِ نَحْوَ دينِهِ وَوَطَنِهِ.", "equality in duties"]] },
 { t: "acik", ar: "تَدْريبٌ (٢): ناقِشْ مَعَ فَريقٍ مِنْ زُمَلائِكَ الوَسائِلَ الَّتي تَتَحَقَّقُ بِها المُساواةُ في الحالاتِ التّالِيَةِ", aciklama: "A group activity; then look at the example.", ogeler: [
  ["المُساواةُ بَيْنَ الأَوْلادِ.", "أَنْ يَعْدِلَ الوالِدانِ بَيْنَهُمْ في العَطِيَّةِ وَالمَحَبَّةِ.", "among children"], ["المُساواةُ بَيْنَ الأَغْنِياءِ وَالفُقَراءِ.", "أَنْ يَقِفوا أَمامَ القاضي سَواءً، وَأَنْ تُحْفَظَ كَرامَةُ الفَقيرِ.", "between rich and poor"],
  ["المُساواةُ بَيْنَ الحُكّامِ وَالمَحْكومينَ.", "أَنْ يَخْضَعَ الحاكِمُ لِلْقانونِ كَما يَخْضَعُ لَهُ الشَّعْبُ، كَما فَعَلَ عُمَرُ.", "between ruler and ruled"], ["المُساواةُ بَيْنَ الرُّؤَساءِ وَالمَرْؤوسينَ.", "أَنْ يَحْتَرِمَ الرَّئيسُ مَنْ يَعْمَلونَ مَعَهُ، وَأَلّا يَظْلِمَهُمْ.", "between superior and employee"],
  ["المُساواةُ بَيْنَ الجِنْسَيْنِ (الرِّجالِ وَالنِّساءِ).", "أَنْ يَتَساوَيا في الكَرامَةِ وَالثَّوابِ وَالحُقوقِ الأَساسِيَّةِ، مَعَ مُراعاةِ ما خَصَّ اللهُ بِهِ كُلًّا مِنْهُما.", "between woman and man"]] },
 { t: "acik", ar: "تَدْريبٌ (٣): هَلْ تُوافِقُ أَمْ لا تُوافِقُ؟ وَلِماذا؟", aciklama: "A pair activity; then look at the sample answer.", ogeler: [
  ["يَجِبُ أَنْ تَكونَ هُناكَ مُساواةٌ بَيْنَ العالِمِ وَالجاهِلِ.", "أُوافِقُ في الحُقوقِ أَمامَ القانونِ، وَلا أُوافِقُ في المَنْزِلَةِ؛ قالَ تَعالى: ﴿هَلْ يَسْتَوِي الَّذِينَ يَعْلَمُونَ وَالَّذِينَ لَا يَعْلَمُونَ﴾.", "There should be equality between the scholar and the ignorant."],
  ["يَجِبُ أَنْ نُمَيِّزَ بَيْنَ النّاسِ حَسَبَ أَعْراقِهِمْ.", "لا أُوافِقُ؛ لِأَنَّهُ لا فَضْلَ لِعَرَبِيٍّ عَلى عَجَمِيٍّ إِلّا بِالتَّقْوى.", "People should be distinguished according to their race."],
  ["يَجِبُ التَّمْييزُ بَيْنَ النّاسِ حَسَبَ الأَصْلِ وَالنَّسَبِ.", "لا أُوافِقُ؛ فَالرَّسولُ ﷺ قالَ: لَوْ أَنَّ فاطِمَةَ سَرَقَتْ لَقَطَعْتُ يَدَها.", "Distinction should be made according to lineage and descent."],
  ["يَجِبُ أَنْ تَكونَ هُناكَ مُساواةٌ بَيْنَ الكَبيرِ وَالصَّغيرِ.", "أُوافِقُ في الحُقوقِ وَالقَضاءِ، مَعَ احْتِرامِ الكَبيرِ وَالرَّحْمَةِ بِالصَّغيرِ.", "There should be equality between big and small."],
  ["يَجِبُ التَّمْييزُ بَيْنَ النّاسِ بِناءً عَلى أَمْوالِهِمْ.", "لا أُوافِقُ؛ فَالنّاسُ سَواءٌ في الصَّلاةِ وَأَمامَ القاضي.", "People should be distinguished according to their wealth."],
  ["تَجِبُ المُساواةُ بَيْنَ مُواطِني الدُّوَلِ المُتَقَدِّمَةِ وَالنّامِيَةِ.", "أُوافِقُ؛ فَكُلُّهُمْ بَشَرٌ لَهُمُ الكَرامَةُ نَفْسُها.", "Citizens of developed and developing countries should be equal."]] },
 { t: "acik", ar: "ثانِيًا: التَّعْبيرُ الكِتابِيُّ", aciklama: "Write in your notebook; then look at the sample text.", ogeler: [
  ["تَدْريبٌ (١): أَعِدْ قِراءَةَ نَصِّ (المُساواةُ الحَقَّةُ)، وَقُمْ بِتَلْخيصِهِ بِأُسْلوبِكَ مُسْتَعينًا بِالعَناصِرِ: الإِسْلامُ وَالمُساواةُ، أَمْثِلَةٌ مِنْ صُوَرِ المُساواةِ في التَّكاليفِ الشَّرْعِيَّةِ، المُساواةُ في تَنْفيذِ القِصاصِ، المُساواةُ في القَضاءِ.", "قَرَّرَ الإِسْلامُ مَبْدَأَ المُساواةِ قَبْلَ غَيْرِهِ، وَلَمْ يَكْتَفِ بِتَقْريرِهِ نَظَرِيًّا، بَلْ طَبَّقَهُ النَّبِيُّ ﷺ وَأَصْحابُهُ. فَالتَّكاليفُ الشَّرْعِيَّةُ عامَّةٌ لِكُلِّ مُسْلِمٍ، وَفي الصَّلاةِ يَقِفُ الغَنِيُّ بِجانِبِ الفَقيرِ، وَفي الحَجِّ يَلْبَسُ الجَميعُ لِباسًا واحِدًا. وَالحُدودُ تُقامُ عَلى الشَّريفِ وَالضَّعيفِ، وَقَدْ رَفَضَ الرَّسولُ ﷺ شَفاعَةَ أُسامَةَ في المَخْزومِيَّةِ. وَفي القِصاصِ طَلَبَ عُمَرُ مِنْ رَجُلٍ ضَرَبَهُ أَنْ يَقْتَصَّ مِنْهُ. وَفي القَضاءِ ساوى عُمَرُ بَيْنَ عَلِيٍّ وَخَصْمِهِ، وَاقْتَصَّ لِلْمِصْرِيِّ مِنِ ابْنِ عَمْرِو بْنِ العاصِ.", "Summarize the text in your own style."],
  ["تَدْريبٌ (٢): اكْتُبْ مَوْضوعًا بِعُنْوانِ: (المُساواةُ في حَياةِ الإِنْسانِ)، فيما لا يَقِلُّ عَنْ ٢٠٠ كَلِمَةٍ: أَهَمِّيَّتُها، أَنْواعُها، المُساواةُ عِنْدَ الأُمَمِ القَديمَةِ وَعِنْدَ العَرَبِ قَبْلَ الإِسْلامِ، الإِسْلامُ وَالمُساواةُ، المُساواةُ في المُجْتَمَعاتِ الإِسْلامِيَّةِ وَفي العالَمِ اليَوْمَ (في الغَرْبِ وَالشَّرْقِ)، المُساواةُ عِنْدَ المُنَظَّماتِ الدَّوْلِيَّةِ، عَقَباتُها وَوَسائِلُ عِلاجِها.", "المُساواةُ أَساسُ الأَمْنِ وَالسَّلامِ في المُجْتَمَعِ؛ فَإِذا شَعَرَ النّاسُ بِأَنَّهُمْ سَواءٌ أَمامَ القانونِ عاشوا مُتَحابّينَ. وَمِنْ أَنْواعِها: المُساواةُ أَمامَ القَضاءِ، وَفي الحُقوقِ وَالواجِباتِ، وَفي التَّعْليمِ وَالعَمَلِ. وَقَدْ عَرَفَتِ الأُمَمُ القَديمَةُ طَبَقاتٍ لا تَتَساوى، وَكانَ العَرَبُ قَبْلَ الإِسْلامِ يَفْتَخِرونَ بِالأَنْسابِ وَيَحْتَقِرونَ العَبيدَ. فَجاءَ الإِسْلامُ فَقالَ: ﴿إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ﴾، وَجَعَلَ بِلالًا الحَبَشِيَّ مُؤَذِّنَ الرَّسولِ ﷺ. وَطَبَّقَ المُسْلِمونَ هذا المَبْدَأَ في الصَّلاةِ وَالحَجِّ وَالقَضاءِ. أَمّا اليَوْمَ فَتَتَحَدَّثُ الدُّوَلُ وَالمُنَظَّماتُ الدَّوْلِيَّةُ كَثيرًا عَنِ المُساواةِ، وَلكِنَّها كَثيرًا ما تُفَرِّقُ بَيْنَ القَوِيِّ وَالضَّعيفِ، وَالغَنِيِّ وَالفَقيرِ. وَمِنْ عَقَباتِ المُساواةِ: العَصَبِيَّةُ، وَحُبُّ المالِ وَالسُّلْطانِ، وَالجَهْلُ. وَعِلاجُها بِالتَّرْبِيَةِ الإيمانِيَّةِ، وَنَشْرِ العِلْمِ، وَقَضاءٍ عادِلٍ يُطَبِّقُ القانونَ عَلى الجَميعِ.", "A piece of at least 200 words on “Equality in Human Life”."]] }
]},
// ---------------- DERS 62 ----------------
{ no: 62, kisa: "الإِمْلاءُ: الهَمْزَةُ المُتَوَسِّطَةُ", ar: "الإِمْلاءُ: كِتابَةُ الهَمْزَةِ المُتَوَسِّطَةِ", tr: "Spelling: the hamza in the middle of a word", ozet: "The medial hamza is written according to the strength of the vowels: kasra > ḍamma > fatḥa.", bloklar: [
 { t: "tablo", ar: "كِتابَةُ الهَمْزَةِ المُتَوَسِّطَةِ", bas: ["", "عَلى نَبْرَةٍ (ئ)", "عَلى واوٍ (ؤ)", "عَلى أَلِفٍ (أ) / مُفْرَدَةً (ء)"], satir: [
  ["الحالَةُ", "مَكْسورَةٌ، أَوْ قَبْلَها كَسْرَةٌ", "مَضْمومَةٌ، أَوْ قَبْلَها ضَمَّةٌ", "مَفْتوحَةٌ قَبْلَها فَتْحَةٌ أَوْ ساكِنٌ"],
  ["أَمْثِلَةٌ", "رِئَةٌ، يَئِسَ", "مُؤْمِنٌ، هؤُلاءِ", "رَأْسٌ، يَنْأى، قِراءَةٌ"]] },
 { t: "kural", ar: "الشَّرْحُ", metin: "يُلاحَظُ هُنا أَنَّ القُوَّةَ تَبْدَأُ مِنَ اليَمينِ؛ فَإِنْ كانَ قَبْلَ الهَمْزَةِ المُتَوَسِّطَةِ كَسْرَةٌ أَوْ كانَتْ مَكْسورَةً كُتِبَتْ عَلى نَبْرَةٍ، فَإِنْ لَمْ تَكُنْ كَذلِكَ انْتَقَلْنا إِلى القُوَّةِ الثّانِيَةِ وَهِيَ الضَّمَّةُ، فَإِنْ كانَ ما قَبْلَها ضَمَّةً أَوْ هِيَ مَضْمومَةً تُكْتَبُ عَلى واوٍ، فَإِنْ لَمْ تَكُنْ كَذلِكَ انْتَقَلْنا إِلى القُوَّةِ الأَخيرَةِ الفَتْحَةِ؛ فَإِنْ كانَ قَبْلَها فَتْحَةٌ كُتِبَتْ عَلى أَلِفٍ. وَإِنْ كانَتْ مَفْتوحَةً وَقَبْلَها ساكِنٌ نَظَرْنا في هذا السّاكِنِ: فَإِنْ كانَ صامِتًا كُتِبَتْ عَلى أَلِفٍ (يَنْأى، مَسْأَلَةٌ، يَدْأَبُ)، وَإِنْ كانَ أَلِفًا أَوْ واوًا كُتِبَتْ عَلى السَّطْرِ (مُساءَلَةٌ، تَساءَلَ، سَوْءَةٌ، ضَوْءَهُ)، وَإِنْ كانَ ياءً كُتِبَتْ عَلى نَبْرَةٍ (هَيْئَةٌ، بيئَةٌ، بَطيئَةٌ، شَيْئًا).", tr: "Strength begins from the right: if the hamza has kasra or the letter before it has kasra, it is written on the tooth-seat (nabra); if not, look at the second strongest, ḍamma: if it has ḍamma or the one before it has ḍamma, on a wāw; if not, the last, fatḥa: if the one before it has fatḥa, on an alif. If it has fatḥa and the one before is quiescent: if the quiescent is a sound letter, an alif (يَنْأى، مَسْأَلَةٌ); if alif or wāw, on the line (تَساءَلَ، سَوْءَةٌ); if yāʾ, the nabra (هَيْئَةٌ، شَيْئًا)." },
 { t: "kural", ar: "القاعِدَةُ", metin: "تَعْتَمِدُ كِتابَةُ الهَمْزَةِ المُتَوَسِّطَةِ عَلى قُوَّةِ الحَرَكَةِ: فَالكَسْرَةُ أَقْوى الحَرَكاتِ، تَليها الضَّمَّةُ، فَالفَتْحَةُ. فَإِذا كانَتِ الهَمْزَةُ المُتَوَسِّطَةُ مَكْسورَةً، أَوْ وَقَعَتْ بَعْدَ كَسْرَةٍ أَوْ ياءٍ كُتِبَتْ عَلى ياءٍ مَهْما كانَتْ حَرَكَتُها. إِذا اجْتَمَعَتِ الضَّمَّةُ وَالفَتْحَةُ غَلَبَتِ الضَّمَّةُ، سَواءٌ أَكانَتْ حَرَكَةً لِلْهَمْزَةِ أَوْ لِما قَبْلَها؛ فَتُكْتَبُ الهَمْزَةُ عَلى واوٍ، إِذْ إِنَّ الفَتْحَةَ أَضْعَفُ الحَرَكاتِ تَأْثيرًا؛ فَلا تُكْتَبُ الهَمْزَةُ المُتَوَسِّطَةُ عَلى أَلِفٍ إِلّا إِذا فُتِحَتْ، وَفُتِحَ ما قَبْلَها، أَوْ سُكِّنَ وَهُوَ صَحيحٌ. وَأَمّا إِذا كانَتْ مَفْتوحَةً بَعْدَ أَلِفٍ أَوْ واوٍ ساكِنَةٍ أَوْ مُشَدَّدَةٍ فَإِنَّها تُكْتَبُ مُفْرَدَةً (عَلى السَّطْرِ). الهَمْزَةُ المُتَوَسِّطَةُ السّاكِنَةُ تُكْتَبُ عَلى ما يُناسِبُ حَرَكَةَ ما قَبْلَها.", tr: "The writing of the medial hamza depends on the strength of the vowel: kasra the strongest, then ḍamma, then fatḥa. If the hamza has kasra or comes after kasra or yāʾ, it is written on the nabra. When ḍamma and fatḥa combine, ḍamma prevails: on a wāw. It is written on an alif only if the hamza has fatḥa and the one before has fatḥa or is a quiescent sound letter. After an alif or a quiescent/doubled wāw, if it has fatḥa, it is written on the line. A quiescent hamza is written on the letter matching the vowel before it." },
 { t: "tablo", ar: "تَدْريبٌ (١): صَحِّحِ الخَطَأَ الإِمْلائِيَّ في الكَلِماتِ التّالِيَةِ إِنْ وُجِدَ", tts: false, bas: ["الكَلِمَةُ", "تَصْحيحُها", "الكَلِمَةُ", "تَصْحيحُها"], satir: [
  ["الأَأمة", "الأَئِمَّةُ", "شعاأر", "شَعائِرُ"], ["أجأتنا", "أَجِئْتَنا", "شفعاأنا", "شُفَعاؤُنا"], ["إحياأه", "إِحْياؤُهُ", "شيأا", "شَيْئًا"], ["أخطأوا", "أَخْطَؤوا", "الصابأون", "الصّابِئونَ"],
  ["أساأوا", "أَساؤوا", "طباأع", "طَبائِعُ"], ["إسراأيل", "إِسْرائيلُ", "طراأف", "طَرائِفُ"], ["أسماأه (رَفْعٌ)", "أَسْماؤُهُ", "عباأة", "عَباءَةٌ"], ["أسماأه (نَصْبٌ)", "أَسْماءَهُ", "عقاأد", "عَقائِدُ"],
  ["أسماأه (جَرٌّ)", "أَسْمائِهِ", "علماأنا", "عُلَماؤُنا"], ["أنبياأه", "أَنْبِياؤُهُ", "عندأذ", "عِنْدَئِذٍ"], ["أنبياأهم", "أَنْبِياؤُهُمْ", "الفأاد", "الفُؤادُ"], ["أنشأوا", "أَنْشَؤوا", "فأس", "فَأْسٌ (صَحيحَةٌ)"],
  ["أولأك", "أُولئِكَ", "فراأض", "فَرائِضُ"], ["استأذن", "اسْتَأْذَنَ (صَحيحَةٌ)", "قاأما", "قائِمًا"], ["بأر", "بِئْرٌ", "قاأمة", "قائِمَةٌ"],
  ["تُأَمِّن", "تُؤَمِّنُ", "لَأيم", "لَئيمٌ"], ["تُأَوِّل", "تُؤَوِّلُ", "لجأوا", "لَجَؤوا"], ["تساأل", "تَساءَلَ", "مأبدا", "مُؤَبَّدًا"], ["حقاأق", "حَقائِقُ", "مأة", "مِئَةٌ"],
  ["خطأك (رَفْعٌ)", "خَطَؤُكَ", "المُأَثِّر", "المُؤَثِّرُ"], ["داأبين", "دائِبينَ", "مأجل", "مُؤَجَّلٌ"], ["داأما", "دائِمًا", "مأدب", "مُؤَدَّبٌ"], ["دعاأكم", "دُعاؤُكُمْ", "مأرخ", "مُؤَرِّخٌ"],
  ["دعاأم", "دَعائِمُ", "مأسسة", "مُؤَسَّسَةٌ"], ["رأساء", "رُؤَساءُ", "مألف", "مُؤَلِّفٌ"], ["رأوس", "رُؤوسٌ", "مألفة", "مُؤَلَّفَةٌ"], ["رأوف", "رَؤوفٌ", "المأمنون", "المُؤْمِنونَ"],
  ["الرأى", "الرَّأْيُ", "مأول", "مُؤَوِّلٌ"], ["الرأيا", "الرُّؤْيا", "مأيد", "مُؤَيِّدٌ"], ["رأيس", "رَئيسٌ", "المأدة", "المائِدَةُ"]],
  not: "In the book the words are given with the hamza (wrongly) written on alif; the correct spellings are in the second column. A few words such as «الرأى» and «تُأَوِّل» are not clear in the print; their most probable readings were given. Exercise (2) is a dictation exercise that the teacher reads." }
]},
// ---------------- DERS 63 ----------------
{ no: 63, kisa: "المَفْعولُ لِأَجْلِهِ", ar: "قَواعِدُ اللُّغَةِ (ب): المَفْعولُ لِأَجْلِهِ", tr: "Grammar: the object of purpose (mafʿūl lahu)", ozet: "The accusative mental verbal noun that states the reason for the verb and answers the question ‘why?’; it can be put in the genitive with مِنْ or لِـ.", bloklar: [
 { t: "tablo", ar: "الأَمْثِلَةُ: ادْرُسْ وَتَأَمَّلْ", bas: ["", "الأَمْثِلَةُ"], satir: [
  ["أ", "﴿يُنْفِقُونَ أَمْوَالَهُمُ [[ابْتِغَاءَ]] مَرْضَاتِ اللَّهِ﴾ ﴿وَلَا تَقْتُلُوا أَوْلَادَكُمْ [[خَشْيَةَ]] إِمْلَاقٍ﴾ ﴿يَجْعَلُونَ أَصَابِعَهُمْ فِي آذَانِهِمْ مِنَ الصَّوَاعِقِ [[حَذَرَ]] الْمَوْتِ﴾ ﴿وَلَا تُمْسِكُوهُنَّ [[ضِرَارًا]] لِتَعْتَدُوا﴾"],
  ["ب", "﴿وَإِنَّ مِنْهَا لَمَا يَهْبِطُ [[مِنْ خَشْيَةِ]] اللَّهِ﴾ ﴿وَيُسَبِّحُ الرَّعْدُ بِحَمْدِهِ وَالْمَلَائِكَةُ [[مِنْ خِيفَتِهِ]]﴾ ابْتَعَدْتُ عَنِ المَعاصي [[خَشْيَةً]] لِلّهِ، أَوْ [[لِخَشْيَةِ]] اللهِ، أَوْ [[مِنْ خَشْيَةِ]] اللهِ."],
  ["ج", "[[رَغْبَةً]] في العِلْمِ سافَرْتُ. وَ[[لِلدِّراسَةِ]] سافَرْتُ."],
  ["د", "﴿وَلَا تَقْتُلُوا أَوْلَادَكُمْ مِنْ إِمْلَاقٍ﴾ ﴿وَالْأَرْضَ وَضَعَهَا لِلْأَنَامِ﴾"]] },
 { t: "kural", ar: "الشَّرْحُ", metin: "تَأَمَّلْ ما تَحْتَهُ خَطٌّ في (أ) تَجِدْها مَصادِرَ قَلْبِيَّةً مَنْصوبَةً، جاءَتْ لِبَيانِ عِلَّةِ وُقوعِ الفِعْلِ، وَتُسَمّى مَفْعولًا لِأَجْلِهِ، وَهِيَ جَوابٌ لِلسُّؤالِ: لِمَ حَدَثَ الفِعْلُ؟ فَالمِثالُ الأَوَّلُ: لِمَ يُنْفِقونَ أَمْوالَهُمْ؟ وَالجَوابُ: ابْتِغاءَ مَرْضاةِ اللهِ. وَإِذا كانَ المَصْدَرُ غَيْرَ قَلْبِيٍّ فَإِنَّهُ يُجَرُّ وَلا يُنْصَبُ، كَما في (١٠)، وَإِذا كانَتْ عِلَّةُ الحَدَثِ غَيْرَ مَصْدَرٍ لَمْ تُعْرَبْ مَفْعولًا لِأَجْلِهِ، كَما في (١١). وَيَجوزُ جَرُّ هذا المَصْدَرِ المُسْتَوْفي لِلشُّروطِ بِالحَرْفَيْنِ (مِنْ) أَوِ (اللّامِ)، كَما في (ب). وَيَجوزُ تَقْديمُ المَفْعولِ لِأَجْلِهِ عَلى عامِلِهِ مَنْصوبًا كانَ أَوْ مَجْرورًا، كَما في (ج).", tr: "The underlined words in (أ) are accusative mental verbal nouns that state the reason for the verb: the object of purpose; they answer the question ‘why did the action take place?’. If the verbal noun is not mental (إِمْلاق) it is not accusative but genitive; if the reason is not a verbal noun (الأَنام) it is not an object of purpose. A verbal noun meeting the conditions can be put in the genitive with مِنْ or لِـ (ب); it can also come before its governor (ج)." },
 { t: "kural", ar: "القاعِدَةُ", metin: "المَفْعولُ لِأَجْلِهِ: مَصْدَرٌ قَلْبِيٌّ مَنْصوبٌ، يَأْتي بَعْدَ الفِعْلِ؛ لِبَيانِ عِلَّتِهِ وَسَبَبِهِ، وَهُوَ جَوابٌ لِلسُّؤالِ (لِمَ حَدَثَ الفِعْلُ؟) وَيَجوزُ جَرُّهُ بِمِنْ أَوِ اللّامِ.", tr: "The object of purpose: the accusative mental verbal noun that comes to state the reason for the verb; it answers the question ‘why did the action take place?’; it can be put in the genitive with مِنْ or لِـ." },
 { t: "acik", ar: "تَدْريبٌ (١): ضَعْ خَطًّا تَحْتَ المَفْعولِ لِأَجْلِهِ فيما يَلي", aciklama: "Find it yourself first; then look at the answer.", ogeler: [
  ["﴿فَأَمَّا الَّذِينَ فِي قُلُوبِهِمْ زَيْغٌ فَيَتَّبِعُونَ مَا تَشَابَهَ مِنْهُ ابْتِغَاءَ الْفِتْنَةِ وَابْتِغَاءَ تَأْوِيلِهِ﴾", "ابْتِغاءَ (الفِتْنَةِ)، ابْتِغاءَ (تَأْويلِهِ)", "Desiring to cause trouble and desiring to interpret it…"],
  ["﴿وَمَثَلُ الَّذِينَ يُنْفِقُونَ أَمْوَالَهُمُ ابْتِغَاءَ مَرْضَاتِ اللَّهِ وَتَثْبِيتًا مِنْ أَنْفُسِهِمْ﴾", "ابْتِغاءَ، تَثْبيتًا", "Seeking God's pleasure and to strengthen their souls…"],
  ["﴿وَالَّذِينَ اتَّخَذُوا مَسْجِدًا ضِرَارًا وَكُفْرًا وَتَفْرِيقًا بَيْنَ الْمُؤْمِنِينَ وَإِرْصَادًا لِمَنْ حَارَبَ اللَّهَ وَرَسُولَهُ﴾", "ضِرارًا، وَكُفْرًا، وَتَفْريقًا، وَإِرْصادًا", "Those who took a mosque to cause harm, disbelief, divide the believers and as an outpost…"],
  ["﴿وَلَا تُفْسِدُوا فِي الْأَرْضِ بَعْدَ إِصْلَاحِهَا وَادْعُوهُ خَوْفًا وَطَمَعًا﴾", "خَوْفًا وَطَمَعًا", "Call on Him in fear and hope.", "Some grammarians also explain these as circumstantial."],
  ["﴿تَتَجَافَىٰ جُنُوبُهُمْ عَنِ الْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفًا وَطَمَعًا﴾", "خَوْفًا وَطَمَعًا", "Their sides forsake their beds; they call upon their Lord in fear and hope."],
  ["﴿وَدَّ كَثِيرٌ مِنْ أَهْلِ الْكِتَابِ لَوْ يَرُدُّونَكُمْ مِنْ بَعْدِ إِيمَانِكُمْ كُفَّارًا حَسَدًا مِنْ عِنْدِ أَنْفُسِهِمْ﴾", "حَسَدًا", "Most of the People of the Book, out of envy within themselves…"],
  ["«مَنْ قامَ لَيْلَةَ القَدْرِ إِيمانًا وَاحْتِسابًا، غُفِرَ لَهُ ما تَقَدَّمَ مِنْ ذَنْبِهِ»", "إِيمانًا وَاحْتِسابًا", "Whoever spends the Night of Power in worship, believing and hoping for reward…"],
  ["يُغْضي حَياءً وَيُغْضى مِنْ مَهابَتِهِ ... فَلا يُكَلَّمُ إِلّا حينَ يَبْتَسِمُ", "حَياءً، (مِنْ مَهابَتِهِ: مَجْرورٌ بِمِنْ)", "He lowers his eyes out of modesty, and eyes are lowered before him out of awe…"],
  ["مَشى الشّابُّ خَلْفَ أَبيهِ احْتِرامًا لَهُ.", "احْتِرامًا", "The young man walked behind his father out of respect."],
  ["نَعْطِفُ عَلى اليَتامى رَأْفَةً بِهِمْ.", "رَأْفَةً", "Out of our compassion we show concern for orphans."]] },
 { t: "acik", ar: "تَدْريبٌ (٢): أَجِبْ عَمّا يَلي بِأَجْوِبَةٍ تَشْتَمِلُ عَلى مَفاعيلَ لِأَجْلِها", aciklama: "First answer yourself; then look at the example.", ogeler: [
  ["لِماذا يُلازِمُ الشّابُّ والِدَهُ؟", "يُلازِمُهُ بِرًّا بِهِ.", "Why does the young man not part from his father?"], ["لِماذا نَصومُ يَوْمَ عَرَفَةَ؟", "نَصومُهُ طَلَبًا لِلْأَجْرِ.", "Why do we fast on the day of ʿArafa?"],
  ["لِماذا لا تُسافِرُ مَعَنا غَدًا؟", "لا أُسافِرُ انْشِغالًا بِالدِّراسَةِ.", "Why are you not travelling with us tomorrow?"], ["لِماذا يَحْرِصُ النّاسُ عَلى جَمْعِ النُّقودِ؟", "يَحْرِصونَ عَلَيْهِ خَوْفًا مِنَ الفَقْرِ.", "Why are people keen on hoarding money?"],
  ["لِماذا تَحْمِلُ الأُمُّ طِفْلَتَها؟", "تَحْمِلُها رَحْمَةً بِها.", "Why does the mother take her daughter in her lap?"]] },
 { t: "acik", ar: "تَدْريبٌ (٣): امْلَأْ كُلَّ فَراغٍ مِمّا يَلي بِمَفْعولٍ لِأَجْلِهِ مُناسِبٍ، وَاضْبِطْ آخِرَهُ بِالشَّكْلِ", aciklama: "Write it yourself first; then look at the example.", ogeler: [
  ["أَصومُ … لِأَمْرِ اللهِ.", "أَصومُ طاعَةً لِأَمْرِ اللهِ.", "I fast in obedience to God's command."], ["أُصَلّي … لِلّهِ.", "أُصَلّي خُضوعًا لِلّهِ.", "I pray in submission to God."],
  ["نُساعِدُ الفُقَراءَ وَالمَساكينَ …", "نُساعِدُهُمْ رَحْمَةً بِهِمْ.", "We help the poor and needy out of mercy."], ["يَحْرُثُ الفَلّاحُ أَرْضَهُ …", "يَحْرُثُها طَلَبًا لِلرِّزْقِ.", "The farmer ploughs his field for provision."],
  ["يُحارِبُ القائِدُ الأَعْداءَ …", "يُحارِبُهُمْ دِفاعًا عَنِ الوَطَنِ.", "The commander fights the enemy to defend the homeland."], ["أَتَعَلَّمُ اللُّغَةَ العَرَبِيَّةَ …", "أَتَعَلَّمُها حُبًّا لِلْقُرْآنِ.", "I learn Arabic out of love for the Qur'an."],
  ["هاجَرَ الصَّحابَةُ مِنْ مَكَّةَ إِلى المَدينَةِ …", "هاجَروا فِرارًا بِدينِهِمْ.", "The Companions emigrated from Mecca to Medina to protect their religion."], ["نَلْبَسُ المَلابِسَ الثَّقيلَةَ في الشِّتاءِ …", "نَلْبَسُها اتِّقاءً لِلْبَرْدِ.", "In winter we wear thick clothes to protect ourselves from the cold."],
  ["سَقى الرَّجُلُ الكَلْبَ العَطْشانَ …", "سَقاهُ رَحْمَةً بِهِ.", "The man gave water to the thirsty dog out of mercy for it."], ["أَرْسَلَ اللهُ الرُّسُلَ إِلى البَشَرِيَّةِ …", "أَرْسَلَهُمْ هِدايَةً لِلنّاسِ.", "God sent the messengers to guide humanity."]] },
 { t: "acik", ar: "تَدْريبٌ (٤): أَكْمِلِ الجُمَلَ التّالِيَةَ بِوَضْعِ فِعْلٍ مُناسِبٍ", aciklama: "Write it yourself first; then look at the example.", ogeler: [
  ["… الطُّلّابُ بِجِدٍّ وَنَشاطٍ رَغْبَةً في النَّجاحِ.", "يَدْرُسُ الطُّلّابُ…", "Students work seriously out of desire for success."], ["… الجُنودُ أَسْلِحَتَهُمُ اسْتِعْدادًا لِلْعَدُوِّ.", "يُجَهِّزُ الجُنودُ…", "Soldiers prepare their weapons to get ready for the enemy."],
  ["… المُسْلِمُ إِلى الصَّلاةِ طاعَةً لِلّهِ.", "يُسْرِعُ المُسْلِمُ…", "The Muslim runs to prayer in obedience to God."], ["… خالِدٌ لِزِيارَةِ أَقْرِبائِهِ رَغْبَةً في صِلَتِهِمْ.", "ذَهَبَ خالِدٌ…", "Khālid went to see his relatives."],
  ["… الرَّجُلُ بِيَدِ الأَعْمى إِعانَةً لَهُ.", "أَخَذَ الرَّجُلُ…", "The man took the blind man's hand to help."], ["… كَثيرٌ مِنَ الشَّبابِ وَالشّابّاتِ بِالجامِعاتِ طَلَبًا لِلشَّهادَةِ.", "يَلْتَحِقُ كَثيرٌ…", "Many young people enrol in universities for a diploma."],
  ["… كِتابَ القَواعِدِ العَرَبِيَّةِ اسْتِعْدادًا لِلِاخْتِبارِ.", "راجَعْتُ كِتابَ…", "I reviewed the Arabic grammar book to prepare for the exam."], ["… سَلْمانُ بِالطّائِرَةِ وَلَمْ يُسافِرْ بِالسَّيّارَةِ رَغْبَةً في الرّاحَةِ.", "سافَرَ سَلْمانُ…", "Salmān went by plane for comfort."]] },
 { t: "acik", ar: "تَدْريبٌ (٥): اجْعَلِ الكَلِماتِ التّالِيَةَ مَفْعولًا لِأَجْلِهِ في جُمَلٍ مِنْ إِنْشائِكَ", aciklama: "Write it yourself first; then look at the example.", ogeler: [
  ["مَحَبَّةً", "زُرْتُ صَديقي مَحَبَّةً لَهُ.", "with love"], ["حِرْصًا", "ذاكَرْتُ دُروسي حِرْصًا عَلى النَّجاحِ.", "with greed"], ["إِجْلالًا", "قامَ الطُّلّابُ إِجْلالًا لِلْمُعَلِّمِ.", "with respect"], ["تَعْظيمًا", "سَكَتَ النّاسُ تَعْظيمًا لِلْقُرْآنِ.", "with veneration"],
  ["إِكْرامًا", "ذَبَحَ الرَّجُلُ شاةً إِكْرامًا لِضَيْفِهِ.", "to honour"], ["رَحْمَةً", "أَطْعَمَتِ البِنْتُ القِطَّةَ رَحْمَةً بِها.", "with mercy"], ["مُحافَظَةً", "أَغْلَقْتُ البابَ مُحافَظَةً عَلى البَيْتِ.", "to protect"], ["خَوْفًا", "هَرَبَ الطِّفْلُ خَوْفًا مِنَ الكَلْبِ.", "out of fear"]] },
 { t: "acik", ar: "تَدْريبٌ (٦): أَجِبْ عَنْ كُلِّ سُؤالٍ مِنَ الأَسْئِلَةِ الآتِيَةِ بِجُمْلَةٍ تامَّةٍ تَشْتَمِلُ عَلى مَفْعولٍ لِأَجْلِهِ", aciklama: "First answer yourself; then look at the example.", ogeler: [
  ["لِمَ تُحْسِنُ إِلى الفُقَراءِ؟", "أُحْسِنُ إِلَيْهِمْ رَغْبَةً في الأَجْرِ.", "Why do you do good to the poor?"], ["لِمَ تَبْتَعِدُ عَنِ المَريضِ؟", "أَبْتَعِدُ عَنْهُ خَوْفًا مِنَ العَدْوى.", "Why do you keep away from the sick?"],
  ["لِمَ عُنِيَتِ الدَّوْلَةُ بِنَظافَةِ المُدُنِ؟", "عُنِيَتْ بِها حِرْصًا عَلى صِحَّةِ النّاسِ.", "Why did the state give importance to the cleanliness of cities?"], ["لِمَ تَهْتَمُّ بِلادُكَ بِنَشْرِ التَّعْليمِ؟", "تَهْتَمُّ بِهِ رَغْبَةً في التَّقَدُّمِ.", "Why does your country give importance to spreading education?"],
  ["لِمَ تَقِفُ لِمُعَلِّمِكَ؟", "أَقِفُ لَهُ احْتِرامًا.", "Why do you stand up for your teacher?"], ["لِمَ نَزورُ الأَطِبّاءَ؟", "نَزورُهُمْ طَلَبًا لِلْعِلاجِ.", "Why do we go to doctors?"]] }
]}
];
